def logic_gates(E):
    """Physical logic update and microprocessor graph, verified once and shared by the Logic entries."""
    if hasattr(E, "logic"):
        return E.logic
    n, code, op = E.native, E.code, E.operand
    if not (E.root / LG_REPORT).is_file():
        raise ValueError("Logic report missing: " + LG_REPORT)
    for slot, target in ((LOGIC_SLOT, F_LOGIC), (MICRO_SLOT, F_MICRO)) + MICRO_SLOTS:
        if struct.unpack("<Q", n.raw(slot, 8))[0] != target:
            raise ValueError("Vtable slot %#x does not point to %#x" % (slot, target))
    rep = " Report: %s." % LG_REPORT
    f = {}
    f["dispatch"] = code(F_LOGIC, 0x1403C4E9F, "8b848254953c004803c2ffe0", "Logic gate dispatch", "jump table at 0x1403c9554",
                         "The logic gate update (vtable 0x140b6a1c0, slot +0x358 at 0x140b6a518 holds 0x1403c4d20; the extractor re-reads it) reads the definition's logic_gate_type at +0xe70 and jumps through 63 image-relative entries at 0x1403c9554. "
                         "The component dispatcher makes one call through slot +0x358 per component per update (0x1405498d6). Each case computes its outputs from the input values cached at that moment; no case adds an internal delay." + rep)
    for key, (bid, gtype, entry, hexbytes) in GATES.items():
        if n.base + struct.unpack("<I", n.raw(LOGIC_TABLE + 4 * gtype, 4))[0] != entry:
            raise ValueError("Logic jump-table entry %d does not lead to %#x" % (gtype, entry))
    f["sanitize"] = code(F_SANITIZE, 0x1401E3C51, "6683f8017417", "Finite-value check", "NaN or ±infinity → 0",
                         "The helper classifies its binary32 argument (call 0x1409d2f30) and returns 0 for an infinity, then tests NaN with ucomiss at 0x1401e3c57 (bytes 0f2ef60f9ac0) and returns 0 for it too. Every other value passes unchanged; this is not a clamp to -1 … 1. "
                         "Numeric gate cases call it before they store their output." + rep)
    f["sixty"] = op(F_LOGIC, 0x1403C6458, "f30f590500a37e00", 0x140BB0760, "Seconds-to-updates factor",
                    "Timed physical gates multiply their seconds setting by this and truncate toward zero (cvttss2si, for example at 0x1403c6460, bytes f3480f2cd0) to a whole number of updates N. The delay (0x1403c5224) and blinker (0x1403c5197) do the same. "
                    "Example: 0.51 s × 60 = 30.6, truncated to 30 updates." + rep)
    f["graph_in"] = code(F_GRAPH_IN, 0x1403718E9, "0fb64020", "Microprocessor input gathering", "upstream output +0x20 → input cache +0x38",
                         "Inside a microprocessor graph, a Boolean input node copies its upstream component's output into its own input cache. The graph update gathers every component's inputs before it runs any component's tick (slot +0x50). "
                         "Inference from those two phases: a new result reaches the next component one graph update later, whatever the iteration order." + rep)
    E.logic = f
    return f


def logic(B, E):
    T, P, A = E.tooltip, E.port, E.attr
    f = logic_gates(E)
    n, code, op = E.native, E.code, E.operand
    R = update_rate(E)["findings"]
    rep = " Report: %s." % LG_REPORT
    base = [f["dispatch"]]

    def case(key, value, detail):
        bid, gtype, entry, hexbytes = GATES[key]
        name = E.block(bid)["name"]
        return code(F_LOGIC, entry, hexbytes, "%s case (logic_gate_type %d)" % (name, gtype), value,
                    "Jump-table entry %d at %#x leads here. %s%s" % (gtype, LOGIC_TABLE + 4 * gtype, detail, rep))

    def gate(fid, key, summary, how, value, detail, extra=(), setup=None, limits=(), ports=()):
        bid = GATES[key][0]
        findings = [case(key, value, detail), A(bid, "logic_gate_type", "Selects case %d of the logic update." % GATES[key][1])] + base + list(extra)
        if E.block(bid).get("description"):
            findings.append(T(bid))
        findings += [P(bid, p) for p in ports]
        sections = [section("How it updates", how)] + ([section("Setup and interactions", setup)] if setup else [])
        B.family(fid, summary, sections, findings, list(limits))

    C = " The result passes the finite-value check, so NaN and ±infinity become 0."
    # Boolean gates.
    gate("part-gate-bool-and", "and", "On when A and B are both on.", "Each update the output is A AND B.", "Q = A AND B",
         "Type 0 also takes the default branch for out-of-range types.")
    gate("part-gate-bool-or", "or", "On when A or B is on.", "Each update the output is A OR B.", "Q = A OR B", "Plain OR of the two cached inputs.")
    gate("part-gate-bool-xor", "xor", "On when exactly one of A and B is on.", "Each update the output is on when A differs from B.", "Q = (A ≠ B)",
         "Compares the two cached inputs for inequality.")
    gate("part-gate-bool-not", "not", "Outputs the opposite of A.", "Each update the output is NOT A.", "Q = NOT A", "Inverts the cached input.")
    gate("part-gate-bool-constant", "bconst", "Always outputs on.", "Each update it writes on to its output.", "Q = 1", "Stores 1 to the Boolean output every update.")
    # Numeric gates.
    for fid, key, summary, how, value in (
            ("part-gate-float-add", "add", "Outputs A + B.", "Each update the output is A + B.", "A + B"),
            ("part-gate-float-subtract", "subtract", "Outputs A − B.", "Each update the output is A − B.", "A − B"),
            ("part-gate-float-multiply", "multiply", "Outputs A × B.", "Each update the output is A × B.", "A × B"),
            ("part-gate-float-invert", "invert", "Outputs the negated input.", "Each update the output is −x.", "−x"),
            ("part-gate-float-abs", "abs", "Outputs the absolute value of the input.", "Each update the output is |x|.", "|x|"),
            ("part-gate-float-constant", "fconst", "Outputs its configured number.", "Each update the output is the number set with the select tool.", "configured constant")):
        gate(fid, key, summary, how + " A result that overflows to infinity, or is NaN, outputs 0.", value,
             "Single-precision arithmetic on the cached numeric inputs." + C)
    div = op(F_LOGIC, 0x1403C6549, "0f2f0510937e00", 0x140BAF860, "Divide-by-zero threshold",
             "Divide compares |B| with this. Above it the quotient A ÷ B is computed and Error is off; at or below it the output is 0 and Error is on, without dividing. Modulo uses the same constant (0x1403c5e58).")
    gate("part-gate-float-divide", "divide", "A ÷ B; when |B| ≤ 1e-6 it outputs 0 and turns Error on.",
         "Each update it tests |B|. Above 1e-6 it outputs A ÷ B with Error off. At or below 1e-6 it outputs 0 with Error on.", "A ÷ B, or 0 with Error when |B| ≤ 1e-6",
         "Error is the Boolean output; the quotient is skipped, not clamped, on the error path." + C, [div],
         "Gate downstream logic on Error, because 0 is also a legitimate quotient.", ports=["Error"])
    mod = op(F_LOGIC, 0x1403C5E58, "0f2f15019a7e00", 0x140BAF860, "Modulo divisor threshold",
             "Modulo calls the library remainder helper 0x1409d5b34 only when |B| is above this; otherwise it outputs 0.")
    gate("part-gate-float-modulo", "modulo", "Remainder of A ÷ B; when |B| ≤ 1e-6 it outputs 0.",
         "Each update, with |B| above 1e-6, it outputs the library remainder of A ÷ B. At or below 1e-6 it outputs 0. There is no error output.",
         "remainder(A, B), or 0 when |B| ≤ 1e-6", "The remainder helper is a library routine; its sign and rounding rules follow that library." + C, [mod])
    gate("part-gate-float-clamp", "clamp", "Limits the input to the configured lower and upper bounds.",
         "Each update the output is min(max(x, lower), upper). The bounds are not swapped: if lower is above upper the output is always upper.",
         "min(max(x, lower), upper)", "Reads lower at +0x708 and upper at +0x720 and applies max, then min, in that order." + C)
    gate("part-gate-float-threshold", "threshold", "On when lower ≤ input ≤ upper (both bounds inclusive).",
         "Each update the output is on when lower ≤ x ≤ upper. The bounds are not swapped: with lower above upper it is never on.",
         "lower ≤ x ≤ upper", "Two comparisons against the configured bounds at +0x708 and +0x720; either failure turns the output off.",
         setup="For hysteresis, pair it with an SR latch.")
    gate("part-gate-float-greater-than", "greater", "On when A > B; off when they are equal.", "Each update the output is A > B, strictly.", "A > B",
         "comiss and seta: equal inputs, or a NaN input, give off.")
    gate("part-gate-float-less-than", "less", "On when A < B; off when they are equal.", "Each update the output is A < B, strictly.", "A < B",
         "Strict comparison: equal inputs give off.")
    gate("part-gate-float-switch", "junction", "Routes the value to On Path when Switch Signal is on, otherwise to Off Path; the unused path outputs 0.",
         "Each update, Switch Signal on gives On Path = value and Off Path = 0; Switch Signal off gives On Path = 0 and Off Path = value.",
         "on: (x, 0); off: (0, x)", "Writes both numeric outputs every update.")
    gate("part-gate-float-switch-input", "switchbox", "Outputs First Value (On) when Switch Signal is on, otherwise Second Value (Off).",
         "Each update the output is the first value when Switch Signal is on and the second value when it is off.", "A ? x : y",
         "Selects between the two cached numeric inputs." + C)
    clear = code(F_LOGIC, 0x1403C6309, "f3410f1086d0060000", "Memory register Clear value", "configured reset value",
                 "On Clear the case loads the configured reset value from +0x6d0 and stores it as the held value, after any Set in the same update." + rep)
    gate("part-gate-float-register", "register", "Set stores Value to Store; Clear loads the configured reset value and overrides Set.",
         "Each update, Set copies Value to Store into the held value. Clear then replaces it with the reset value configured with the select tool, so Clear wins when both are on. Otherwise the value holds.",
         "Set: S = x; Clear: S = reset value", "Set writes the cached numeric input to +0x6b8; Clear runs after it." + C, [clear],
         "The tooltip is right: Clear restores the configured value. The Clear port's description of a reset to 0 holds only when that value is 0.",
         ports=["Clear"])
    trig = op(F_LOGIC, 0x1403C6A42, "f30f5e05069b7e00", 0x140BB0550, "Trigonometry turn factor",
              "The forward modes multiply the input by this 2π constant before calling sin, cos or tan; the inverse modes divide the helper result by it. asin and acos first compare |x| with 1 and output 0 above it. "
              "The mode order sin, cos, tan, asin, acos, atan is inferred from the six helper calls and their domains.")
    gate("part-gate-float-sin", "trig", "Trigonometry in turns: forward functions take turns, inverse functions return turns, invalid input outputs 0.",
         "When the input changes it evaluates the selected function: sin, cos and tan of x × 2π, or asin, acos and atan of x divided by 2π. asin and acos of |x| > 1 output 0. An unchanged input leaves the output as it was.",
         "f(2π·x) or f⁻¹(x) ÷ 2π", "Mode at +0x148, six cases; the result is published through the finite-value path 0x1403c9d10." + C, [trig],
         "Sensors that report turns (compass, tilt, radar angles) feed it directly without degree or radian conversion.")
    eps = E.const(F_POWER_GUARD, 0x140BAF85C, "Exponent zero guard",
                  "The guard returns 'suppress' when (x < this and k < 1) or (|x| < this and k < this), x being the input and k the exponent; the case then outputs 0.")
    guard = code(F_LOGIC, 0x1403C6AD7, "e824d1e1ff", "Exponent guard call", "call 0x1401e3c00",
                 "On a changed input the case calls the guard and outputs 0 when it returns true; otherwise it calls the library power helper 0x1409b9c10 with x and k." + rep)
    gate("part-gate-float-exponent", "exponent", "Raises the input to the configured exponent; inputs below 1.1920929e-7 with an exponent below 1 output 0.",
         "When the input changes it outputs x^k through a library power helper. A guard outputs 0 instead when x is below 1.1920929e-7 and k below 1, which includes every negative input with such an exponent, or when |x| and k are both below 1.1920929e-7. A NaN result, such as a negative base with a fractional exponent of 1 or more, outputs 0.",
         "x^k with a near-zero guard", "Reads the exponent property through 0x1402dc0c0." + C, [eps, guard])
    func = "%s%s" % ("On a changed x, y or z, and only when its expression parsed (flags +0x830 and +0x831), it calls the expression evaluator 0x1401e5360. ", C)
    gate("function-gate", "function", "Re-evaluates its expression only when an input changes; NaN and infinity output 0.",
         "The output updates on an update where x, y or z changed, and only if the expression parsed. Unchanged inputs keep the last result. Function (1 input) and Function (3 inputs) share this case.",
         "f(x, y, z) on input change", func, [case("function_large", "f(x, y, z) on input change", func), A("gate_function_large", "logic_gate_type", "Selects case 45 of the logic update.")],
         setup="Treat the operator set and rounding as the editor documents them; the Logic category lists what of the expression language remains open.")
    # Stateful Boolean gates.
    jk_guard = code(F_LOGIC, 0x1403C63F2, "3ac27509443ac10f84f3300000", "JK changed-input guard", "skip when Set and Reset are unchanged",
                    "The case saves Set and Reset at +0x691 and +0x692 and compares them with the previous values; when neither changed it jumps to the common exit without touching the state." + rep)
    jk_toggle = code(F_LOGIC, 0x1403C6407, "4138b6b40600000f94c0", "JK toggle", "Q = NOT Q",
                     "With both inputs on after a change, the state at +0x6b4 is complemented. Set alone sets it, Reset alone clears it, neither holds it. Output and NOT Output follow the state." + rep)
    micro_jk = code(F_MICRO_JK, 0x14037AF78, "44388120010000750f", "Microprocessor JK guard", "same changed-input guard",
                    "The microprocessor JK flip-flop (vtable 0x140ae7928, slot +0x50) compares Set and Reset with the values saved at +0x120 and +0x121 and applies the same set, reset, toggle and hold table only when one changed." + rep)
    gate("part-gate-jk-flipflop", "jk", "Acts only when Set or Reset changes: Set sets, Reset resets, both on toggles once. Holding both on does not keep toggling.",
         "On an update where Set or Reset changed: Set on and Reset off sets the output, Reset on and Set off resets it, both on toggles it, both off holds it. On an update where neither input changed the output holds, whatever the inputs are. Inputs that change together count as one change.",
         "on change: 10 set, 01 reset, 11 toggle, 00 hold", "Example from the report with Q starting off: inputs 00, 11, 11, 11, 01, 11 give Q 0, 1, 1, 1, 0, 1.", [jk_guard, jk_toggle, micro_jk],
         "To toggle repeatedly with both inputs on, pulse one of them: each new change to both on toggles once. The microprocessor JK flip-flop follows the same rule.")
    gate("part-gate-sr-latch", "sr", "Reset wins when Set and Reset are both on; it acts only when an input changes.",
         "On an update where Set or Reset changed: Reset on clears the output, even with Set on; otherwise Set on sets it; both off hold it. Unchanged inputs hold.",
         "on change: Reset clears, else Set sets", "Saves both inputs at +0x691 and +0x692 and skips the update when neither changed; Reset is tested first.",
         setup="Use the JK flip-flop instead if both on should toggle.")
    gate("part-gate-push-to-toggle", "toggle", "Toggles its state on each rising edge of Toggle Signal.",
         "On an update where Toggle Signal turns on, Internal State flips. Holding the signal on, or turning it off, leaves the state unchanged.",
         "on rising edge: Q = NOT Q", "Compares the input with the value saved at +0x691; only a change to on complements the state at +0x3a8.")
    # Timers.
    sixty, ex = f["sixty"], " For example 0.51 s × 60 = 30.6, truncated to 30 updates."
    blink60 = op(F_LOGIC, 0x1403C5197, "f30f100dc1b57e00", 0x140BB0760, "Blinker seconds-to-updates factor",
                 "The blinker multiplies both durations by this and truncates them to whole updates.")
    gate("part-gate-bool-blink", "blink", "Blinks for whole numbers of updates: on for trunc(60 × on time), off for trunc(60 × off time), while Control Signal is on.",
         "The two durations become N_on = trunc(60 × on time) and N_off = trunc(60 × off time) updates. When Control Signal changes the cycle counter restarts at 0. Otherwise the counter advances by 1 each update and wraps after N_on + N_off. The output is on while Control Signal is on and the counter is below N_on, so each cycle gives N_on updates on and N_off off." + ex,
         "on while c < N_on, period N_on + N_off", "On duration from +0x6e0, off duration from +0x6dc, counter at +0x6e4; the counter test is unsigned.", [blink60, sixty] + R,
         "The microprocessor Blinker is a different routine: it starts each call off and spends its wrap update off, so after the first cycle it gives one update fewer on.",
         [TICK])
    delay60 = op(F_LOGIC, 0x1403C5224, "f30f590534b57e00", 0x140BB0760, "Delay seconds-to-updates factor",
                 "The delay multiplies its setting by this and truncates it to N updates.")
    gate("part-gate-bool-delay", "delay", "Copies its input to the output once the input has stayed unchanged for trunc(60 × delay) updates; any change restarts the count.",
         "With N = trunc(60 × delay), a change of Signal to Delay resets the counter to 0 and leaves the output as it was. Each following update with the input unchanged adds 1, and when the counter reaches N the output takes the input. The output therefore follows a change N updates later, and a signal that flips sooner never passes." + ex + " With N = 0 the output never changes, because the counter test c < N fails at once.",
         "Q = input after N stable updates", "Counter at +0x6e4, saved input at +0x691; the c < N test precedes the increment.", [delay60, sixty] + R, limits=[TICK])
    cap = code(F_LOGIC, 0x1403C6460, "f3480f2cd0", "Capacitor tick count", "N = trunc(60 × seconds)",
               "The capacitor truncates 60 × charge time and 60 × discharge time to N_charge and N_discharge, then compares each counter with N before incrementing it." + rep)
    gate("part-gate-bool-capacitor", "capacitor", "Turns on after Charge has been on for trunc(60 × charge time) updates and off after it has been off for trunc(60 × discharge time).",
         "Any change of Charge clears both counters. While the output is off and Charge is on, the charge counter is compared with N_charge, the output turns on when they are equal, then the counter adds 1. While the output is on and Charge is off, the discharge counter works the same way against N_discharge. With N_charge = 60 a rising Charge at update 0 turns the output on at update 60, the 61st update including the edge. A charge time of 0 turns it on in the edge update." + ex,
         "on after N_charge updates of Charge, off after N_discharge without", "Example: N_charge = 60 gives on at update 60 after the edge at update 0. The microprocessor Capacitor follows the same recurrence. This Boolean count is not an electrical battery model.",
         [cap, sixty] + R, limits=[TICK])
    # Counters and Up/Down.
    gate("part-gate-float-counter", "counter", "Adds Speed to Count every update, 60 × Speed per simulated second.",
         "Each update Count = Count + Speed. There is no division by 60, so a Speed of 1 counts 60 per simulated second.",
         "S = S + Speed per update", "The running sum is the numeric output at +0x418; the sum passes the finite-value check each update." + C, R, limits=[TICK])
    gate("part-gate-float-counter-ping-pong", "pingpong", "Adds ±Speed every update and reverses direction when Count passes 1 or −1.",
         "Each update Count = Count + direction × Speed. Above 1 it is set to 1 and the direction becomes −1; below −1 it is set to −1 and the direction becomes +1. Reaching exactly ±1 does not reverse. With Speed 0.01 a sweep from −1 to 1 takes 200 updates.",
         "S = S ± Speed, bounce at ±1", "Direction byte at +0x6a0; the bounds are the constants 1 and -1. Example: Speed 0.01 crosses 2 units in 200 updates." + C, R, limits=[TICK])
    ud = op(F_LOGIC, 0x1403C4F5C, "f30f5e0dfcb77e00", 0x140BB0760, "Up/Down step divisor",
            "The step is (upper − lower) × sensitivity ÷ this per update, so the full range takes 1 ÷ sensitivity simulated seconds.")
    gate("part-gate-up-down", "updown", "Up and Down move the value by (upper − lower) × sensitivity ÷ 60 per update, clamped to the configured bounds.",
         "Each update, Up adds the step h = (upper − lower) × sensitivity ÷ 60 and Down subtracts it; both on cancel. The value is then clamped to lower … upper. Holding Up moves across the whole range in 1 ÷ sensitivity simulated seconds.",
         "S = clamp(S + h·(Up − Down), lower, upper)", "Bounds at +0x7a0 and +0x7b8, sensitivity at +0x6a4, value at +0x6b8." + C, [ud] + R,
         "Drive robotic joints, throttles or rudders directly from its output.", [TICK])
    # PID controller.
    pid = pid_controller(E)
    B.family("part-gate-pid-controller",
             "Per-update PID: Control Output = Ki·S + Kp·e + Kd·(e − e_prev), with e = Setpoint − Process Variable and S the running sum of e. There is no dt, no derivative filter and no output limit.",
             [section("How it updates",
                      "Each update with Active on: e = Setpoint − Process Variable, S = S + e, d = e − e_prev, and Control Output = Ki × S + Kp × e + Kd × d. "
                      "Arithmetic is single precision in that order. On the first update after Active turns on, d is 0. Turning Active off sets S, e_prev and the output to 0."),
              section("Timebase",
                      "Nothing is multiplied by a time step. S gains 60 errors per simulated second and d is the change over one update. "
                      "Converting from per-second gains (an inference about tuning conventions, not engine code): Ki = Ki_per_second ÷ 60 and Kd = 60 × Kd_per_second. With Ki = 1 and a constant error of 1, the output reaches 60 after one simulated second."),
              section("Limits and edge cases",
                      "max_error (pid_controller_max_error) is the only limit. When it is above 0, S is clamped to ±max_error ÷ max(1e-8, Ki), so the integral term Ki × S stays within ±max_error for positive Ki. It does not limit P, D or Control Output. "
                      "A NaN or infinite output becomes 0. The derivative acts on the error, so a Setpoint step gives a one-update kick of Kd × step."),
              section("Microprocessor PIDs",
                      "The microprocessor PID and advanced PID run the same recurrence without the max_error clamp and without the finite-value check, so their sum and output are unbounded. "
                      "Example: Kp 2, Ki 0.5, Kd 0 and a steady error of 2 give 5, 6, 7 in a microprocessor; the physical PID with max_error 1 holds S at 2 and gives 5, 5, 5."),
              section("Setup and interactions",
                      "Set max_error to bound windup when the driven part saturates. Toggle Active off to clear the stored sum. Start with small Ki: a per-update sum grows 60 times faster than a per-second integral.")],
             pid + [T("gate_pid_controller"), P("gate_pid_controller", "Active"), P("gate_pid_controller", "Setpoint"), P("gate_pid_controller", "Process Variable"),
                    A("gate_pid_controller", "logic_gate_type", "Selects case 29 of the logic update."), f["dispatch"]] + R,
             [TICK])
    # Transmission and train parts that sit in the logic update.
    for fid, key, name in (("part-gate-torque-add", "torque_add", "Power Add"), ("part-gate-torque-multimeter", "torque_meter", "Power Meter")):
        bid = GATES[key][0]
        B.family(fid, "%s does nothing in the logic update; it acts in the transmission network." % name,
                 [section("How it updates",
                          "Its logic_gate_type case jumps straight to the common exit, so the logic update computes nothing for it. Its effect belongs to the transmission network; the Logic category lists what remains open.")] +
                 ([section("Setup and interactions", "Place it between engine and consumer, not on a branch.")] if key == "torque_meter" else []),
                 [case(key, "no logic calculation", "Types 24 and 25 both lead to the common exit 0x1403c94f2."), A(bid, "logic_gate_type", "Selects a case with no calculation."), f["dispatch"]] + ([T(bid)] if E.block(bid).get("description") else []),
                 [])
    gate("part-gate-train-junction", "train", "Drives a train-junction helper object, not a Boolean toggle; its tooltip and ports copy Push To Toggle.",
         "Its case creates or updates a junction helper through 0x140290d10 and the object stored at +0x840. Its tooltip and ports are word for word those of Push To Toggle.",
         "junction helper", "Compares a flag at +0x831 first; the helper object is kept at +0x840.", [T("gate_push_to_toggle")],
         "Expect it to switch a track junction rather than to feed other logic; the Logic category lists what of its routing remains open.")
    # Microprocessor.
    mp = microprocessor(E)
    co = composite_native(E)
    tp = tanks_ports_native(E)
    per_cell = E.derived("Ports per position for the bridged kinds", "at most 4; 144 on a 6 by 6 grid (not confirmed)",
                         "Inference from the placement rule: the five kinds the bridge builder 0x1403929f0 supports are 0, 1, 5, 6 and 7 (on/off, number, composite, video, audio). "
                         "Kinds 0 and 1 conflict, so one position holds at most one of them plus one each of 5, 6 and 7: 4 ports, or 4 × 36 = 144 on the largest grid. "
                         "No accepted 144-port microcontroller was built or loaded. Report: %s." % TP_REPORT, [co["port_kind"], co["port_xz"], co["dim_max"]])
    B.family("part-microprocessor",
             "A microcontroller in a block: each update it copies its connected inputs into an embedded logic graph, runs the graph, then copies the graph outputs back out. Composite bridges copy all 32 on/off and 32 number channels, video bridges a descriptor and audio bridges the samples.",
             [section("How it updates",
                      "Component type 37 runs the microprocessor update. It calls every input bridge, then the graph update with the embedded graph at +0x1c0, then every output bridge. "
                      "Each bridge copies one value: an input bridge reads the connected vehicle signal into a graph node, and an output bridge writes a graph output to the connected signal. Bridges with no connection do nothing."),
              section("Ports",
                      "The definition lists no logic nodes and no tooltip. The ports come from the bridges of the embedded graph, with number, on/off, composite, video and audio bridge types. Read the ports from the microcontroller you placed, not from the definition."),
              section("Composite, video and audio bridges",
                      "A composite bridge copies the whole 132-byte value, the on/off mask and all 32 numbers, between the connected signal and its graph node, in both directions. "
                      "A video bridge copies the fixed video descriptor field by field and allocates nothing. An audio bridge copies the samples into a buffer the receiving side owns. "
                      "No bridge converts one kind into another: video and audio never enter composite channels."),
              section("Size and port placement",
                      "The editor's width and length controls run from 1 to 6 in steps of 1, and the upload check rejects a microcontroller whose width or length is above 6 with \"Microcontroller must not be larger than 6x6 voxels\". "
                      "A port must sit inside the grid, 0 ≤ x < width and 0 ≤ z < length, in the bottom row y = 0. Two ports at one position are rejected when they have the same kind, or kinds 0 and 1 (internal codes); other kinds may share a position. "
                      "This rule sets no total, so the 6 by 6 area and the 32 composite channels do not give a port limit."),
              section("Port and graph counts",
                      "Add Input allocates a node, gives it the next node ID, creates its bridge and appends it to the port list. It grows the list when it is full and never compares the count with a maximum. The upload check tests the size, that the graph and port lists are not empty, that an output exists and where each port sits, but not how many ports there are.",
                      "The binary format stores the port count in 16 bits and the embedded component count in 32 bits. These are field widths, not editor limits: the serializers check no count against them, and XML lists grow as they are read. "
                      "Inference, not tested in game: with the five bridged kinds at most 4 ports fit one position, one on/off or number port plus one composite, one video and one audio, so 144 on a 6 by 6 grid."),
              section("Composite channels inside the graph",
                      "The composite read nodes (on/off and number) clamp their channel to 1 to 32, so channel 0 or less reads channel 1 and anything above 32 reads channel 32. A channel taken from an input is rounded first by adding 0.5 (inference: the library call is floor). "
                      "Lua getBool and getNumber instead return false and 0 outside 1 to 32, setBool and setNumber ignore such channels, and setNumber rounds the Lua number to binary32. The Logic category gives the channel layout."),
              section("Inside the graph",
                      "The graph gathers every component's inputs before it runs any component, so a change moves one component per update (inference). Its components are separate routines from the physical gates: the PID has no max_error clamp, and the Blinker differs, as their part pages note.")],
             mp + [A("microprocessor", "type", "Component type 37, the microprocessor class."), A("microprocessor", "category", "Definition category 5, the game's logic category."), f["graph_in"]]
             + [co[k] for k in ("b_co_in", "b_co_out", "b_co_gather", "b_vid_in", "b_vid_out", "b_aud_in", "b_aud_out", "vid_copy", "aud_alloc", "aud_copy",
                                "dim_min", "dim_max", "upload", "upload_msg", "port_xz", "port_kind", "readb", "readn", "read_half", "getb", "getn", "setb", "setn", "n_getb", "n_setb")]
             + [tp[k] for k in ("mc_add", "mc_append", "mc_nodes_read", "mc_nodes_write", "mc_comps", "mc_upload")] + [per_cell],
             ["No unconditional maximum port or graph size was recovered across editor creation, XML import, binary saves and graph execution. ID validation and allocation in other creation paths were not traced, "
              "and whether the 144 ports the placement rule allows for the five bridged kinds are accepted end to end is not confirmed.",
              CO_POINTER])
    # Category.
    B.category("Logic",
               "All logic gates run in one native update, once per update. Boolean gates are plain; latches and flip-flops act only when an input changes; timers count whole updates; numeric outputs replace NaN and infinity with 0.",
               [section("How logic updates",
                        "Each gate is one case of the logic update, chosen by its logic_gate_type through a jump table. The component dispatcher calls it once per component per update, 60 times per simulated second. "
                        "A case computes its outputs from the input values it holds at that moment and adds no delay of its own."),
                section("Numeric outputs",
                        "Arithmetic is single precision. Numeric gates pass their result through a finite-value check that turns NaN and ±infinity into 0. That check does not limit values to −1 … 1."),
                section("Edge cases worth knowing",
                        "Divide outputs 0 and turns Error on when |B| ≤ 1e-6; Modulo outputs 0 for the same divisor. Threshold is on when lower ≤ x ≤ upper. Greater Than is off when A equals B. "
                        "Trigonometry works in turns, and asin or acos of |x| > 1 gives 0. The SR latch favours Reset. The JK flip-flop and SR latch act only on an update where an input changed, so holding both JK inputs on toggles once, not every update. "
                        "Clear on the memory register restores the configured value."),
                section("Timers count updates",
                        "Delay, Blinker and Capacitor multiply their seconds by 60 and truncate to whole updates; 0.51 s becomes 30 updates. Counters and Up/Down step every update. The PID has no time step at all."),
                section("Inside a microprocessor",
                        "A microprocessor gathers every component's inputs before it runs any component, so a signal moves one component per update inside it (inference). Its PID, Blinker and timers are separate routines; see the PID Controller and Microprocessor pages."),
                section("Between logic blocks",
                        "A physical output keeps its value in its own slot, and an input reads only its own cached copy. After every component on every vehicle has updated, the dispatcher walks each vehicle's outputs and pushes each value into every input wired to it: on/off as a byte, numbers as binary32, composite as the whole 132-byte value. "
                        "Inference from that order: a change moves one block per update along a chain of physical logic blocks on one vehicle, the same rule as inside a microprocessor."),
                section("Composite channel layout",
                        "A composite signal carries 32 on/off channels and 32 numbers, both numbered 1 to 32, in one 132-byte value. Wires, microprocessor bridges and Electrical Cable Anchors copy it whole, as connectors and radios do on their links.",
                        "Table: Composite value layout\n"
                        "| Part | Bytes | Channel c |\n"
                        "| --- | --- | --- |\n"
                        "| On/off mask | one 32-bit word at byte 0 | bit c − 1 |\n"
                        "| Numbers | 32 binary32 values from byte 4 to the end | 4 bytes from byte 4 × c |",
                        "Table: Channels outside 1 to 32\n"
                        "| Access | Channel 0 or below, above 32 |\n"
                        "| --- | --- |\n"
                        "| Lua getBool, getNumber | false, 0 |\n"
                        "| Lua setBool, setNumber | ignored |\n"
                        "| Microprocessor composite read nodes | clamped to channel 1 or 32 |",
                        "Example: on/off channels 1, 3 and 32 on give the mask bytes 05 00 00 80, and number channel 1 = 1.5 is stored at byte 4 as 00 00 c0 3f. setNumber rounds a Lua number to binary32.")],
               [f["dispatch"], f["sanitize"], f["sixty"], f["graph_in"], div, trig, jk_guard, T("gate_float_threshold"), T("gate_float_greater_than"), T("gate_sr_latch")] + R
               + [co[k] for k in ("fl_bool", "fl_f32", "fl_co", "set_co", "flush", "transport", "getb", "getn", "setb", "setn", "readb", "readn", "b_co_in", "a_comp")],
               ["Timing between vehicles and through cables is listed with the open questions of the Composite data over electrical cables mechanics article.",
                "Sign, rounding and domain edge cases of the library helpers behind Modulo, Exponent and Trigonometry were not decoded.",
                "The function block's expression language (operator set, parser, rounding and constant expressions) was not decoded.",
                "Power Add and Power Meter do nothing in the logic update; their transmission-network formulas were not decoded.",
                "Train Junction Controller routing, junction selection and the priority of conflicting requests were not traced.",
                TICK])


def pid_controller(E):
    """PID recurrence of the physical gate and the two microprocessor PIDs; shared with the PID graph."""
    if hasattr(E, "pid"):
        return E.pid
    f = logic_gates(E)
    n, code, op = E.native, E.code, E.operand
    rep = " Report: %s." % LG_REPORT
    F = F_LOGIC
    out = [
        code(F, 0x1403C5F50, "4989b670070000", "PID inactive reset", "S = e_prev = 0, output 0",
             "With Active off the case stores a zero qword over S (+0x770) and e_prev (+0x774), clears the derivative-valid flag at +0x692 and writes 0 through the finite-value check to Control Output (+0x418)." + rep),
        code(F, 0x1403C5F74, "f30f5cf0", "PID error", "e = Setpoint − Process Variable",
             "subss subtracts the first numeric input (Process Variable, +0x1c0) from the second (Setpoint, +0x1e0) in binary32." + rep),
        code(F, 0x1403C5F7B, "f3410f588e70070000", "PID error sum", "S = S + e",
             "Adds the error to the stored sum at +0x770 every update, with no time-step factor." + rep),
        code(F, 0x1403C5F99, "0f2fda7630", "PID max_error test", "clamp only when max_error > 0",
             "Compares max_error (+0x788) with 0 and skips the clamp when it is 0 or less." + rep),
        op(F, 0x1403C5F9E, "f30f1005ae987e00", 0x140BAF854, "PID bound denominator floor",
           "Loaded before maxss with Ki (+0x738 at 0x1403c5fa6): the denominator is max(1e-8, Ki), not |Ki|."),
        code(F, 0x1403C5FAF, "f30f5ed8", "PID sum limit", "L = max_error ÷ max(1e-8, Ki)",
             "divss forms the limit L from max_error and the floored Ki." + rep),
        code(F, 0x1403C5FBD, "f30f5fc8f30f5dcb", "PID sum clamp", "S = min(max(S, −L), L)",
             "maxss with −L, then minss with L, stored back to +0x770. Only the sum is clamped; P, D and the output are not." + rep),
        code(F, 0x1403C5FCE, "4138b692060000740c", "PID first-enable derivative guard", "d = 0 on the first active update",
             "The derivative-valid flag at +0x692 is 0 after a reset, so d stays 0; it is set to 1 after the output is written (0x1403c6024)." + rep),
        code(F, 0x1403C5FDA, "f3410f5c9674070000", "PID derivative difference", "d = e − e_prev",
             "Subtracts the previous error (+0x774) from the current one. The current error is saved to +0x774 after the output. There is no filter state." + rep),
        code(F, 0x1403C5FEC, "f30f59c1", "PID integral term", "Ki × S", "Multiplies Ki (+0x738) by the clamped sum." + rep),
        code(F, 0x1403C5FF3, "f3410f598e50070000", "PID proportional term", "Kp × e", "Multiplies the error by Kp (+0x750) and adds it to Ki × S." + rep),
        code(F, 0x1403C6000, "f3410f599668070000", "PID derivative term", "Kd × d", "Multiplies d by Kd (+0x768) and adds it last: (Ki·S + Kp·e) + Kd·d." + rep),
        code(F, 0x1403C600D, "e82edce1ff", "PID output finite check", "call 0x1401e3c40",
             "Control Output is the sum after the finite-value check: NaN or ±infinity becomes 0, every finite value passes unchanged." + rep),
    ]
    names = [E.string(F_PID_PROPS, address, name, "PID property %s" % name,
                      "The logic property serializer binds this name to the property object at %s, whose value is read at %s by the PID case." % (obj, val))
             for address, name, obj, val in ((0x140B6B710, "pid_controller_ki", "+0x728", "+0x738"), (0x140B6B750, "pid_controller_kp", "+0x740", "+0x750"),
                                             (0x140B6B738, "pid_controller_kd", "+0x758", "+0x768"), (0x140B6B7B8, "pid_controller_max_error", "+0x778", "+0x788"))]
    micro = []
    for func, label, addr, hexbytes, sum_at in ((F_MICRO_PID, "Microprocessor PID tick", 0x14037A236, "f30f589180010000", "+0x180"),
                                                (F_MICRO_APID, "Microprocessor advanced PID tick", 0x140381386, "f30f5891f8010000", "+0x1f8")):
        start, body = n.body(func)
        if b"\xe8" in body or b"\x0f\x5d" in body or b"\x0f\x5f" in body:
            raise ValueError("Microprocessor PID %#x now contains a call or min/max byte pattern" % func)
        micro.append(code(func, addr, hexbytes, label, "S = S + e, no clamp, no finite check",
                          "Adds the error to the sum at %s, then forms Ki·S + Kp·e + Kd·d with the same first-enable guard and inactive reset. The whole function, %#x-%#x, contains no call byte (e8) and no minss or maxss opcode, so neither the max_error clamp nor the finite-value check runs. "
                          "Example: Kp 2, Ki 0.5, Kd 0 and a steady error of 2 give 5, 6, 7 here and 5, 5, 5 in the physical PID with max_error 1, where S holds at 2. Kp 2, Ki 0.5, Kd 3 with errors 1, 1, 2 give 2.5, 3, 9 in both." % (sum_at, start, start + len(body)) + rep))
    E.pid = out + names + micro + [f["sanitize"]]
    return E.pid


def microprocessor(E):
    """Microprocessor update: bridges around the embedded graph."""
    f = logic_gates(E)
    code = E.code
    rep = " Report: %s." % LG_REPORT
    path = DEFS + "microprocessor.xml"
    _, line, _ = E.at(path, r"<logic_nodes/>")
    empty = E.located(path, line, line, "Microprocessor · logic nodes", "<logic_nodes/>",
                      "microprocessor: the definition's logic node list is empty, so it fixes no ports. The ports come from the embedded graph's bridges.")
    return [empty,
            code(F_MICRO, 0x1403945B0, "ff5058", "Microprocessor input bridges", "slot +0x58 per bridge",
                 "Microprocessor vtable 0x140b84dc8, slot +0x358 at 0x140b85120, holds 0x140394500; the extractor re-reads it. The update walks the bridge list at +0x270 (count +0x280) and calls each bridge's input method through slot +0x58." + rep),
            code(F_MICRO, 0x1403945C7, "e8a48cffff", "Microprocessor graph update", "call 0x14038d270",
                 "After the input bridges it passes the embedded graph at +0x1c0 to the graph update, which gathers component inputs and then runs each component's tick through slot +0x50, recursing into nested groups." + rep),
            code(F_MICRO, 0x140394610, "ff5048", "Microprocessor output bridges", "slot +0x48 per bridge",
                 "After the graph update the same bridge list is walked again and each bridge's output method is called through slot +0x48." + rep),
            code(F_BRIDGE_IN, 0x140371909, "0fb64018", "Boolean input bridge", "vehicle signal +0x18 → graph cache +0x38",
                 "Reads the connected vehicle signal value and stores it in the graph node's cache at +0x38; with no connection it returns at once. RTTI also names number, composite, video and audio bridge classes." + rep),
            code(F_BRIDGE_OUT, 0x14037175D, "884218", "Boolean output bridge", "graph output +0x20 → vehicle signal +0x18",
                 "Writes the graph node's output value into the connected vehicle signal; with no connection it returns at once." + rep)]


# small-parts pass; files under investigation/native/small-parts/, report investigation/small-parts.md.
SP_REPORT = "investigation/small-parts.md"
SP_DATA = "investigation/native/small-parts/parts.json"
F_ITEMS = 0x140001DC0         # equipment item table initializer: one constructor call per item
F_ITEM_CTOR = 0x140264610     # item table entry constructor: capacity at +0x48, recharge time at +0x4c
F_INV = 0x140396995           # chained unwind chunk of the inventory update 0x140396950 (vtable 0x140b655d8 slot +0x358)
F_EADD = 0x1402EEC80          # electricity deposit helper (leaf): adds charge to the group pool
F_GUARD = 0x1402645F0         # two-flag guard (leaf) called at the start of the fuel cell case
F_LASER_GATE = 0x1403C96CB    # chained unwind chunk of the laser point acquisition 0x1403c9670: forward-dot gate
F_LASER_OUT = 0x1403C9B83     # chained unwind chunk of 0x1403c9670: output projections and stores
F_MB_UPDATE = 0x140357A60     # multibody component update, vtable 0x140b02a08 slot +0x358
ITEM_TABLE = 0x140CF2060      # equipment item table, 200 bytes per entry
FACTORY_TABLE = 0x1404B9AD0   # second factory's jump table, image-relative dwords indexed by definition type
FACTORY_MAIN_TABLE = 0x14045E8A4  # main factory's jump table
SP_SLOTS = ((0x140B65930, 0x140396950), (0x140B02D60, F_MB_UPDATE))
SP_RTTI = ((0x140B655D8, "c_scene_vehicle_component_inventory"), (0x140B02A08, "c_scene_vehicle_component_multibody"))
_SP = "small-parts/asm/"
SP_ASM = {
    F_ITEMS: ("small-parts/tools/item-initializers.asm", None), F_INV: (_SP + "equipment.asm", "140396950.c"),
    F_FLUID: (_SP + "fuel-cell-cryo.asm", "1403ef860.c"), F_EADD: (_SP + "electric-add.asm", "1402eec80.c"),
    F_GUARD: (_SP + "fluid-guard.asm", None), F_LASER_GATE: (_SP + "laser.asm", "1403c9670.c"), F_LASER_OUT: (_SP + "laser.asm", "1403c9670.c"),
    F_FACTORY_B: (_SP + "component-factory.asm", "1404b8f30.c"), F_FACTORY: ("keel-windows/asm/factory-main.asm", None), F_JOINT_CTOR: (_SP + "piston-constructor.asm", None),
    F_MB_UPDATE: (_SP + "multibody-update.asm", "140357a60.c"),
}
WHERE[(F_ITEM_CTOR, None)] = "../small-parts/pseudocode/140264610.c"
LIQUID_NAMES = ("fresh_water", "diesel", "jet_fuel", "oil", "seawater", "slurry", "saturated_slurry")
SP_PLAIN = "Static analysis of one build; no game process was run."
SP_STATIC = "Static analysis of one build. Charge is in the game's internal electrical units, as on the Electricity pages; fluid amounts are stored amounts, 10 L of liquid or 600 L of expanded gas per amount."


def small_parts_native(E):
    """Equipment rack charging, cryo cooler, hydrogen fuel cell, laser point sensor and pumpjack piston, verified once and shared."""
    if hasattr(E, "small"):
        return E.small
    n = E.native
    if not (E.root / SP_REPORT).is_file():
        raise ValueError("Small-parts report missing: " + SP_REPORT)
    for slot, target in SP_SLOTS:
        if struct.unpack("<Q", n.raw(slot, 8))[0] != target:
            raise ValueError("Vtable slot %#x does not point to %#x" % (slot, target))
    for vtable, name in SP_RTTI:
        if _rtti(n, vtable) != name:
            raise ValueError("RTTI at %#x is not %s" % (vtable, name))
    case = lambda table, t: n.base + struct.unpack("<I", n.raw(table + 4 * t, 4))[0]
    for t, target in ((33, 0x1403F4D1E), (34, 0x1403F2B03)):
        if case(WATER_TABLE, t) != target:
            raise ValueError("Fluid-update case %d does not select %#x" % (t, target))
    if case(FACTORY_TABLE, 7) != 0x1404B915B or case(FACTORY_MAIN_TABLE, 7) != 0x14045DF0E:
        raise ValueError("Factory case 7 moved")
    for at, hexbytes in ((0x14045DF1F, "e85c85efff"), (0x1404B916C, "e80fd3e9ff")):
        if n.raw(at, 5).hex() != hexbytes:
            raise ValueError("Multibody constructor call at %#x moved" % at)
    rep = " Report: %s." % SP_REPORT

    def code(func, address, hexbytes, label, value, detail):
        _wheel_cite(E, func, address, hexbytes, table=SP_ASM)
        return E.code(func, address, hexbytes, label, value, detail + rep)

    def op(func, address, hexbytes, target, label, detail):
        _wheel_cite(E, func, address, hexbytes, table=SP_ASM)
        return E.operand(func, address, hexbytes, target, label, detail + rep)

    near = lambda a, b: math.isclose(a, b, rel_tol=1e-6, abs_tol=1e-12)
    ups = update_rate(E)["ups"]
    data = json.loads((E.root / SP_DATA).read_bytes())
    if data["target_sha256"] != EXE_SHA256:
        raise ValueError("Small-parts figures were built for a different executable")
    parts = {d["definition"]: d for d in data["parts"]}
    f = {}

    # Equipment rack: item table, gas branch, electric draw and recharge.
    f["i_ctor"] = E.code(F_ITEM_CTOR, 0x1402646B8, "f30f10842480000000f30f114648f30f108c2488000000f30f114e4c", "Item capacity and recharge time", "argument 7 → +0x48, argument 8 → +0x4c",
                         "The item table constructor stores its seventh argument, the charge capacity C, at entry+0x48 and its eighth, the recharge time T in seconds, at entry+0x4c." + rep)
    f["i_table"] = code(F_INV, 0x140396999, "4869f1c8000000", "Rack item entry", "item ID × 200",
                        "The rack update indexes the item table at 0x140cf2060 (lea at 0x1403969d3) with the stored item's ID (component+0x148) times 200 bytes.")
    f["i_gas"] = code(F_INV, 0x1403969AC, "83f8010f866501000083f9010f845c01000083f9030f845301000081f9950000000f8447010000", "Gas-refilled items", "IDs 79, 80, 1, 3 and 149",
                      "ID - 79 ≤ 1 (lea at 0x1403969a0), ID 1, ID 3 and ID 149 jump to the gas refill branch at 0x140396b1a; every other item takes the electric branch.")
    f["i_defib"] = code(F_INV, 0x1403969DA, "83f909752d", "Defibrillator uses", "full charge → one stored use",
                        "For item 9 a charge at or above capacity, with the use count (component+0x150) below the item's limit (entry+0x40), adds one use and resets the charge to 0, so charging starts again.")
    f["i_full"] = code(F_INV, 0x140396A0C, "f30f10443e4c0f57f60f2fc60f861f020000f30f10443e480f2f834c0100000f860c020000", "Rack charging condition", "T > 0 and c < C",
                       "The electric branch returns when the item's recharge time is not positive or its charge c (component+0x14c) is not below capacity C. A full item draws nothing.")
    f["i_group"] = code(F_INV, 0x140396A40, "4883bb88010000000f84ef010000", "Rack electric group test", "no group → no charging",
                        "Without infinite electricity (0x140396a36) a rack whose electric node has no group (component+0x188) skips charging.")
    f["i_supply"] = op(F_INV, 0x140396A59, "f30f100d979d8100", 0x140BB07F8, "Rack supply factor",
                       "a = max(0, (300 - EMP) ÷ 300) × the published charge fraction (component+0x1a4, 0x140396a81); with infinite electricity a = 1 (0x140396a8b).")
    f["i_req"] = op(F_INV, 0x140396A93, "f30f1015bd8e8100", 0x140BAF958, "Rack charge request",
                    "The request R per update. The branch multiplies it by a (0x140396aa2).")
    f["i_draw"] = code(F_INV, 0x140396AB2, "f30f5dcbf30f5cc1f30f5ecaf30f114104", "Rack withdrawal", "w = min(0.01 × a, E); E - w; fraction w ÷ 0.01",
                       "Takes the smaller of 0.01 × a and the pool charge E (group pool+4), removes it from the pool and divides it by 0.01 to get the supplied fraction. The rack does this itself rather than through the shared draw helper.")
    f["i_gate"] = code(F_INV, 0x140396AC3, "0f2fca0f8671010000", "Rack recharge gate", "fraction > 0.01",
                       "The item charges only when the supplied fraction is above 0.01. The charge step does not scale with the fraction, so partial supply above 0.01 charges at full speed; at or below it the withdrawal still happens.")
    f["i_rate"] = code(F_INV, 0x140396AE5, "f30f10743948f30f5ef0f30f59f7", "Rack recharge step", "C ÷ T × ticks",
                       "Divides the capacity by the recharge time and multiplies by the update's tick count (xmm7, 1 for a normal update, converted at 0x140396985).")
    f["i_60"] = op(F_INV, 0x140396AF3, "f30f5935918e8100", 0x140BAF98C, "Rack recharge time scale",
                   "Multiplies the step by 1 ÷ 60, so T is in simulated seconds at 60 updates per second.")
    f["i_store"] = code(F_INV, 0x140396B03, "f30f10443e48f30f5dc6f30f11834c010000", "Rack charge store", "c = min(C, c + step)",
                        "Adds the step to the stored charge and clamps it to the capacity.")
    for slot in ("i_ctor", "i_table", "i_gas", "i_full", "i_req", "i_draw", "i_gate", "i_rate", "i_60", "i_store"):
        if slot not in f:
            raise ValueError("Missing rack finding " + slot)

    # Every constructor call in the initializer, decoded from the bytes: ID from the lea, C and T from the stack stores.
    start = n.function(F_ITEMS)[0]
    body = n.raw(start, n.function(F_ITEMS)[1] - start)
    calls = [start + p for p in range(len(body) - 5) if body[p] == 0xE8 and start + p + 5 + struct.unpack_from("<i", body, p + 1)[0] == F_ITEM_CTOR]

    def stored(call, slot):
        for k in range(call - 6, call - 0x200, -1):
            if n.raw(k, 6) == bytes.fromhex("f30f114424") + bytes([slot]):
                if n.raw(k - 8, 4).hex() == "f30f1005":
                    target = k + struct.unpack("<i", n.raw(k - 4, 4))[0]
                    return n.f32(target), k - 8, target
                if n.raw(k - 3, 3).hex() == "0f57c0":
                    return 0.0, k - 3, None
                raise ValueError("Unexpected store source at %#x" % k)
        raise ValueError("No argument store before %#x" % call)
    items = {}
    for c in calls:
        lea = n.raw(c - 7, 7)
        entry = c + struct.unpack("<i", lea[3:])[0]
        if lea[:3].hex() != "488d0d" or (entry - ITEM_TABLE) % 200:
            raise ValueError("Item constructor call at %#x has no table lea" % c)
        items[(entry - ITEM_TABLE) // 200] = (c, stored(c, 0x30), stored(c, 0x38))
    if len(items) != 155:
        raise ValueError("Item initializer no longer has 155 entries")
    gas = (1, 3, 79, 80, 149)
    electric = sorted(i for i, (_, cap, t) in items.items() if cap[0] > 0 and t[0] > 0 and i not in gas)
    rack = parts["inventory_small"]
    if (parts["inventory_medium"]["electric_items"] != rack["electric_items"] or sorted(rack["gas_refill_ids"]) != list(gas)
            or [d["id"] for d in rack["electric_items"]] != electric or not near(rack["request_per_update"], n.f32(0x140BAF958))
            or not near(rack["request_per_simulated_second"], n.f32(0x140BAF958) * ups)):
        raise ValueError("Rack figures in %s differ from the verified bytes" % SP_DATA)
    for bid in ("inventory_small", "inventory_medium"):
        if E.block(bid)["attributes"]["type"] != "32":
            raise ValueError(bid + " is no longer type 32")
    by_item = {}
    for b, blk in E.blocks.items():
        if b.startswith("inventory_equipment_"):
            by_item.setdefault(int(blk["attributes"]["inventory_default_item"]), []).append(b)
    rows = []
    for d in rack["electric_items"]:
        i = d["id"]
        c, (cap, cap_at, cap_va), (t, t_at, t_va) = items[i]
        defs = ["inventory_" + x if not x.startswith("inventory_") else x for x in d["definitions"]]
        if (d["capacity"] != cap or d["recharge_seconds"] != t or by_item.get(i) != defs or len(defs) != 1
                or not near(d["recharge_percent_per_update"], cap / (ups * t)) or not near(d["nominal_full_recharge_cost"], rack["request_per_simulated_second"] * t)
                or not d["call"].startswith("%x:" % c)):
            raise ValueError("Item %d figures differ from the verified bytes" % i)
        bid = defs[0]
        name = re.sub(r"^Equipment inventory \((.*)\)$", r"\1", E.block(bid)["name"])
        call = n.raw(c, 5).hex()
        _wheel_cite(E, F_ITEMS, c, call, table=SP_ASM)
        x = E.code(F_ITEMS, c, call, "Item %d · %s" % (i, name), "C = %s, T = %s s" % (fmt(cap), fmt(t)),
                   "Constructor call for item %d, table entry %#x. Argument 7, C = %s, is binary32 at %#x (movss at %#x); argument 8, T = %s seconds, is binary32 at %#x (movss at %#x). "
                   "From empty at full supply the rack charges it in %s simulated seconds for %s internal charge (%s)." % (
                       i, ITEM_TABLE + 200 * i, fmt(cap), cap_va, cap_at, fmt(t), t_va, t_at, _g(t), _g(d["nominal_full_recharge_cost"]), SP_DATA) + rep)
        rows.append({"id": i, "bid": bid, "name": name, "C": cap, "T": t, "finding": x,
                     "attr": E.attr(bid, "inventory_default_item", "Item ID this equipment definition holds."),
                     "cls": E.attr(bid, "inventory_class", "Equipment size class; the small rack has inventory_class 1, the medium rack 2.")})
    R = rack["request_per_update"]
    flash = next(r for r in rows if r["id"] == 15)
    if rack["example"] != {"item": "inventory_equipment_flashlight", "seconds_from_empty": int(flash["T"]), "total_internal_charge": int(R * ups * flash["T"])}:
        raise ValueError("Rack worked example differs")
    f["i_rows"] = rows
    f["i_s"] = per_second(E, "Rack charge draw per simulated second", "%s per update, %s per simulated second" % (_g(R), _g(R * ups)),
                          "A charging item at full supply withdraws %s internal charge per update, %s per simulated second. Charging from empty to full takes T simulated seconds, so it costs %s × T: %s for the flashlight's %s s. "
                          "The charge rises by 100 ÷ (60 × T) percentage points per update, %s for the flashlight (%s)." % (
                              _g(R), _g(R * ups), _g(R * ups), _g(R * ups * flash["T"]), _g(flash["T"]), _g(100 / (ups * flash["T"]), 4), SP_DATA) + rep)

    # Cryo cooler.
    cryo = parts["cryo_cooler"]
    h = heat_exchangers(E)
    req, cut, frac = n.f32(0x140BAF8F8), n.f32(0x140BAFAD0), n.f32(0x140BAFA00)
    ex = cryo["example"]
    qa, qb = ex["qA"], ex["qB"]
    if (cryo["water_component_type"] != int(E.block("cryo_cooler")["attributes"]["water_component_type"]) or not near(cryo["electric_request_per_update"], req)
            or not near(cryo["electric_request_per_simulated_second"], req * ups) or not near(cryo["minimum_draw_fraction_exclusive"], cut)
            or tuple(cryo["q_per_liquid_litre"]) != LIQUID_NAMES or len(LIQUID_NAMES) != len(CAPACITY_SLOTS["liquid"]) or set(cryo["q_per_liquid_litre"].values()) != {0.1}
            or not near(qa, ex["liquid_litres_A"] / 10) or not near(ex["delta_A_C_per_update"], -0.03 * qb / (qa + qb)) or not near(ex["delta_B_C_per_update"], 0.03 * qa / (qa + qb))
            or not near(ex["mutual_heat_litre_C_per_update"], 10 * 0.03 * qa * qb / (qa + qb)) or not near(frac, 0.03)):
        raise ValueError("Cryo figures in %s differ from the verified bytes" % SP_DATA)
    f["c_req"] = code(F_FLUID, 0x1403F4F35, "f30f103dbba97b004180beb804000000747f0f28cf498d8eb8020000e84a9defff", "Cryo electricity request", "R = 0.001 per update",
                      "With On/Off on (component+0x4b8) the case loads 0.001 (0x140baf8f8) and passes it to the shared draw helper 0x1402eeca0, which withdraws min(R × a, E) and returns the supplied fraction.")
    f["c_gate"] = op(F_FLUID, 0x1403F4F56, "0f2f0573ab7b00", 0x140BAFAD0, "Cryo supply gate",
                     "Cooling runs only when the supplied fraction is above this; the step itself does not scale with the fraction.")
    f["c_q"] = code(F_FLUID, 0x1403F4F5F, "498d8e98050000e87566efff0f28f0498d8ee4050000e86666efff", "Cryo capacities", "qA, qB = liquid helper",
                    "Both sides call the liquid capacity helper 0x1402eb5e0: A at component+0x598, B at +0x5e4. Gas in either side adds nothing to q.")
    f["c_step"] = code(F_FLUID, 0x1403F4F86, "f30f590572aa7b00f30f5ec3f3410f108edc050000f30f5cc8", "Cryo temperature step", "TA - 0.03 × qB ÷ (qA + qB)",
                       "Subtracts 0.03 × qB ÷ (qA + qB) from A's temperature (+0x5dc); B's (+0x628) gains 0.03 × qA ÷ (qA + qB) at 0x1403f4fa8.")
    dA, dB = ex["delta_A_C_per_update"], ex["delta_B_C_per_update"]
    f["c_ex"] = E.derived("Cryo cooler example", "1 L each side: A %s °C, B +%s °C per update" % (_g(dA), _g(dB)),
                          "q is the stored liquid amount, 0.1 per litre for each of the %d liquids (%s). With 1 L in each circuit qA = qB = %s, so each powered update moves A by %s °C and B by +%s °C before the ambient step, "
                          "%s and +%s °C per simulated second while q holds. The moved quantity 0.03 × qA × qB ÷ (qA + qB) is %s amount × °C, %s L × °C, per update. Full supply costs %s internal charge per update, %s per simulated second (%s)." % (
                              len(LIQUID_NAMES), ", ".join(x.replace("_", " ") for x in LIQUID_NAMES), _g(qa), _g(dA), _g(dB), _g(dA * ups), _g(dB * ups),
                              _g(0.03 * qa * qb / (qa + qb)), _g(ex["mutual_heat_litre_C_per_update"]), _g(req), _g(req * ups), SP_DATA) + rep,
                          [f["c_step"], f["c_q"], h["q_liquid"], f["c_req"]] + update_rate(E)["findings"][:1])

    # Hydrogen fuel cell.
    cell = parts["hydrogen_fuel_cell"]
    o2, h2, water, one = n.f32(0x140BAF8A0), n.f32(0x140BAF8C4), n.f32(0x140BAFA00), n.f32(0x140BAFECC)
    cx = cell["example"]
    if (cell["water_component_type"] != int(E.block("hydrogen_fuel_cell")["attributes"]["water_component_type"]) or not near(cell["oxygen_amount_per_update"], o2)
            or not near(cell["hydrogen_amount_per_update"], h2) or not near(cell["water_amount_per_update"], water) or cell["electric_charge_per_update"] != one
            or not near(cell["oxygen_expanded_L_per_second"], o2 * 600 * ups) or not near(cell["hydrogen_expanded_L_per_second"], h2 * 600 * ups)
            or not near(cell["water_L_per_second"], water * 10 * ups) or cell["electric_charge_per_second"] != one * ups
            or not near(cx["oxygen_expanded_L"], o2 * 600 * cx["active_updates"]) or not near(cx["hydrogen_expanded_L"], h2 * 600 * cx["active_updates"])
            or not near(cx["water_L"], water * 10 * cx["active_updates"]) or cx["electric_charge"] != one * cx["active_updates"]):
        raise ValueError("Fuel cell figures in %s differ from the verified bytes" % SP_DATA)
    f["h_guard"] = code(F_FLUID, 0x1403F2B03, "e8e81ae7ff84c00f848d250000", "Fuel cell guard call", "call 0x1402645f0",
                        "Case 34 starts by calling the guard and skips the whole case when it returns 0. The electrolyser case calls the same guard (0x1403f292b).")
    f["h_flags"] = code(F_GUARD, F_GUARD, "803d615ea90000740c803d595ea900007403b001c3", "Fuel cell guard", "bytes 0x140cfa458 and 0x140cfa459 both nonzero",
                        "Returns 1 only when both global bytes are set. They are game-wide flags, not component state; the directional antennas use the same guard.")
    f["h_o2"] = code(F_FLUID, 0x1403F2B4F, "ba0a000000", "Fuel cell oxygen filter", "fluid slot 10",
                     "The first inlet (component+0x148) exchanges into the shared input (+0x598) with a filter for slot 10, oxygen; the second (+0x180) uses slot 12, hydrogen (0x1403f2bb0).")
    f["h_damage"] = code(F_FLUID, 0x1403F2C05, "e876e6d4ff85c00f85a6000000", "Fuel cell damage test", "damaged → no reaction",
                         "A nonzero result from 0x140141280, the component damage state, skips the reaction; the outlet still exchanges.")
    f["h_oa"] = op(F_FLUID, 0x1403F2C1B, "f30f101d7dcc7b00", 0x140BAF8A0, "Oxygen per reaction",
                   "The reaction needs at least this much oxygen (+0x5cc, jb at 0x1403f2c26) and subtracts it (0x1403f2c61).")
    f["h_ha"] = op(F_FLUID, 0x1403F2C35, "f30f102587cc7b00", 0x140BAF8C4, "Hydrogen per reaction",
                   "The reaction needs at least this much hydrogen (+0x5d4, jb at 0x1403f2c40) and subtracts it (0x1403f2c6e).")
    f["h_wa"] = op(F_FLUID, 0x1403F2C54, "f30f103da4cd7b00", 0x140BAFA00, "Water per reaction",
                   "The water buffer's free space, capacity (+0x5ec) minus contents (+0x624), must be at least this (0x1403f2c5c), and fresh water (slot 0, +0x5f0) gains this (0x1403f2c90).")
    f["h_one"] = op(F_FLUID, 0x1403F2B1C, "f30f1035a8d37b00", 0x140BAFECC, "Fuel cell charge per reaction",
                    "Loaded into xmm6, copied into xmm1 at 0x1403f2cb0 and passed to the deposit helper 0x1402eec80 at 0x1403f2cb3. The branch tests no battery demand or pool room first.")
    f["h_add"] = code(F_EADD, F_EADD, "488b41204885c074160f57c00f2fc8760e488b4020f30f584804f30f114804c3", "Charge deposit helper", "E + c when a group exists",
                      "Adds a positive c to the group pool charge E (pool+4). With no electrical group the charge is dropped while the gases are still used.")
    per = lambda a, k: a * k * ups
    f["h_s"] = E.derived("Fuel cell rates", "%s L/s oxygen, %s L/s hydrogen, %s L/s water, %s charge/s" % (_g(per(o2, 600), 4), _g(per(h2, 600), 4), _g(per(water, 10), 4), _g(one * ups)),
                         "One reaction per update uses %s amount of oxygen and %s of hydrogen, %s and %s expanded litres at 600 L per gas amount, adds %s amount of water, %s L at 10 L per liquid amount, and deposits %s internal charge. "
                         "At %d reactions per simulated second that is %s L/s oxygen, %s L/s hydrogen, %s L/s water and %s charge/s; %d reactions, %s simulated seconds, use %s L and %s L and make %s L of water and %s charge (%s)." % (
                             fmt(o2), fmt(h2), _g(o2 * 600, 4), _g(h2 * 600, 4), fmt(water), _g(water * 10, 4), _g(one), ups, _g(per(o2, 600), 4), _g(per(h2, 600), 4), _g(per(water, 10), 4), _g(one * ups),
                             cx["active_updates"], _g(cx["active_updates"] / ups), _g(cx["oxygen_expanded_L"], 4), _g(cx["hydrogen_expanded_L"], 4), _g(cx["water_L"], 4), _g(cx["electric_charge"]), SP_DATA) + rep,
                         [f["h_oa"], f["h_ha"], f["h_wa"], f["h_one"]] + update_rate(E)["findings"][:1])

    # Laser point sensor.
    las = parts["laser_point_sensor"]
    den, gate = n.f32(0x140BAFE18), n.f32(0x140BAFCBC)
    cone = 2 * math.degrees(math.acos(gate))
    edge = math.sin(math.radians(cone / 2)) / den
    lx = las["example"]
    if (las["logic_gate_type"] != int(E.block("laser_point_sensor")["attributes"]["logic_gate_type"]) or las["denominator"] != den or den != struct.unpack("<f", struct.pack("<f", math.cos(0.5)))[0]
            or las["forward_dot_minimum_exclusive"] != gate or not near(las["full_cone_degrees"], cone) or not near(las["open_cone_axis_output_bound"], edge)
            or not near(lx["horizontal_output"], math.sin(math.radians(lx["angle_from_forward_degrees"])) / den) or lx["vertical_output"] != 0):
        raise ValueError("Laser figures in %s differ from the verified bytes" % SP_DATA)
    f["l_gate"] = op(F_LASER_GATE, 0x1403C9A5F, "440f2f0d55627e00767e", 0x140BAFCBC, "Laser acceptance gate",
                     "The acquisition 0x1403c9670 forms the dot product of the unit direction to a laser point with the sensor's forward axis (0x1403c9a45-0x1403c9a5a) and rejects the point unless it is above this (jbe). "
                     "Among accepted points it keeps the largest dot product, subject to the wavelength, range and visibility checks.")
    f["l_div"] = op(F_LASER_OUT, 0x1403C9C96, "f30f5e2d7a617e00f30f5e1572617e00", 0x140BAFE18, "Laser output divisor",
                    "Both output projections, the unit direction dotted with the sensor's two lateral axes, are divided by this binary32 cos(0.5 rad).")
    f["l_store"] = code(F_LASER_OUT, 0x1403C9CA6, "f30f11af00050000f30f1197fc040000838ff804000001", "Laser outputs", "number 1 = +0x4fc, number 2 = +0x500, on/off 1 set",
                        "Stores the two quotients as composite numbers 1 and 2 and sets composite on/off bit 1. With no accepted point the outputs and the bit are cleared.")
    sx = lx["horizontal_output"]
    f["l_ex"] = E.derived("Laser point sensor outputs", "x = sin(angle) ÷ %s for a point on the x axis; at most %s at the edge" % (fmt(den), _g(edge)),
                          "A dot product above %s means at most %s degrees from forward, a %s degree cone. A point %d degrees to one side reads %s; one near the %s degree edge reads up to %s, never 1. "
                          "So the outputs are scaled direction components, not angles. For a point on one axis, angle = asin(%s × output) (%s)." % (
                              fmt(gate), _g(cone / 2), _g(cone), lx["angle_from_forward_degrees"], _g(sx), _g(cone / 2), _g(edge), fmt(den), SP_DATA) + rep,
                          [f["l_gate"], f["l_div"], f["l_store"]])

    # Oil Rig Pumpjack B.
    pj = parts["oil_rig_pumpjack_b"]
    b, a = E.block("oil_rig_pumpjack_b"), E.block("oil_rig_pumpjack")["attributes"]
    if (pj["definition_type"] != int(b["attributes"]["type"]) or pj["mass"] != float(b["attributes"]["mass"]) or int(b["attributes"]["flags"]) & 0x80 != pj["fluid_update_skipped_by_flag"]
            or pj["oil_component_type"] != int(b["attributes"]["oil_component_type"]) or pj["logic_ports"] != len(b["logic"]) or a["child_name"] != pj["parent_child_name"]
            or a["type"] != "7" or int(a["flags"]) & 0x80 or pj["own_oil_amount_per_update"] != 0 or pj["own_fluid_outlet"]):
        raise ValueError("Pumpjack figures in %s differ from the definitions" % SP_DATA)
    f["p_case"] = code(F_FACTORY, 0x14045DF0E, "b998040000", "Factory case 7", "c_scene_vehicle_component_multibody",
                       "Definition type 7 selects 0x14045df0e in the main factory's jump table (entry at 0x14045e8c0), which allocates 0x498 bytes and calls the multibody constructor 0x140356480 at 0x14045df1f. "
                       "The second factory 0x1404b8f30 does the same at 0x1404b916c.")
    f["p_ctor"] = code(F_JOINT_CTOR, 0x1403564A6, "488d055bc57a00488906", "Multibody vtable", "0x140b02a08",
                       "The constructor installs this vtable; its update slot +0x358 at 0x140b02d60 holds 0x140357a60, which the extractor re-reads.")
    f["p_flag"] = code(F_MB_UPDATE, 0x140357A79, "4c8b4158498b80b802000048a9800000000f87f4010000", "Multibody update flag test", "flags & 0x80 → return; own output 0",
                       "Reads the definition flags (definition+0x2b8) and jumps to the epilogue at 0x140357c84 when bit 0x80 is set, so the update does nothing. Without the bit it needs a fluid port (+0x148) and a network (+0x250).")
    path = DEFS + "oil_rig_pumpjack_b.xml"
    m, line, _ = E.at(path, r"<logic_nodes/>")
    f["p_ports"] = E.located(path, line, line, "Oil Rig Pumpjack B · ports", "none", "oil_rig_pumpjack_b: empty <logic_nodes/>, so the piston has no fluid, logic or power port.")
    E.small = {"f": f, "ups": ups, "R": R, "cryo": (req, cut, frac), "cell": (o2, h2, water, one), "laser": (den, gate, cone, edge, sx)}
    return E.small


def small_parts(B, E):
    S = small_parts_native(E)
    f, ups = S["f"], S["ups"]
    T, P, A = E.tooltip, E.port, E.attr
    R = update_rate(E)["findings"]
    N = electricity_native(E)
    h = heat_exchangers(E)

    # Equipment racks.
    rows = f["i_rows"]
    rack_rate = S["R"]
    table = "\n".join("- %s (item %d, inventory_class %s): %s s, %s charge from empty" % (
        r["name"], r["id"], r["cls"]["value"], _g(r["T"]), _g(rack_rate * ups * r["T"])) for r in rows)
    rack = [f[x] for x in ("i_ctor", "i_table", "i_gas", "i_defib", "i_full", "i_group", "i_supply", "i_req", "i_draw", "i_gate", "i_rate", "i_60", "i_store", "i_s")]
    B.family("empty-equipment-inventory",
             "Recharges a stored rechargeable item by drawing %s internal charge per update, %s per simulated second, until the item is full." % (_g(rack_rate), _g(rack_rate * ups)),
             [section("Setup and interactions", "Small units take only small handheld equipment, medium units large equipment; connect Electric to charge."),
              section("Charge draw",
                      "While a stored item is below full, the rack withdraws up to %s internal charge from its electrical network each update, %s per simulated second. "
                      "It scales that request by max(0, (300 - EMP) ÷ 300) × the network's charge fraction and takes no more than the pool holds. "
                      "If the supplied share is above %s the item gains 100 ÷ (60 × T) percentage points that update, where T is the item's recharge time; partial supply above that share charges at full speed. "
                      "An empty rack and a full item draw nothing, and a rack with no electrical network does not charge." % (_g(rack_rate), _g(rack_rate * ups), _g(rack_rate))),
              section("Recharge time per item",
                      "From empty to full at full supply, in simulated seconds, and the charge that costs. inventory_class 1 items go in the small rack and class 2 items in the medium rack, matching the racks' own inventory_class:\n\n" + table + "\n\n"
                      "The defibrillator turns each full charge into a stored use while it is below its use limit, then charges again, so the listed cost is per use. "
                      "Diving gear, scuba gear, both space suits and the firefighter breathing set (items 1, 3, 79, 80 and 149) refill through the gas branch instead and draw no charge here.")],
             rack + [x for r in rows for x in (r["finding"], r["attr"], r["cls"])] + R
             + [T("inventory_small"), T("inventory_medium"), A("inventory_small", "inventory_class", "Small rack class."), A("inventory_medium", "inventory_class", "Medium rack class.")],
             [SP_STATIC, TICK])

    # Cryo cooler: the per-update constants are also cited in more_families' heat entries.
    req, cut, frac = S["cryo"]
    step = E.const(F_FLUID, 0x140BAFA00, "Cryo transfer fraction",
                   "Case 0x21 (cryo_cooler) subtracts 0.03·qB/(qA+qB) from compartment A's temperature and adds 0.03·qA/(qA+qB) to B's each update, a fixed transfer independent of the temperature gap.")
    floor = E.const(F_FLUID, 0x140BAF8F8, "Cryo electric demand and ambient leak",
                    "The cryo cooler requests this much electricity per update, requires qA+qB above it, and both compartments drift toward the surrounding temperature by this fraction.")
    cryo_s = per_second(E, "Cryo transfer and demand per simulated second", "%.3g·qB/(qA+qB) and %.3g·qA/(qA+qB); demand %.3g" % (frac * ups, frac * ups, req * ups),
                        "60 × the per-update temperature transfer and electricity request, with q held constant.")
    B.family("part-cryo-cooler", "Pumps heat from liquid A to liquid B by a fixed amount per update, even against the gradient, for %s internal charge per update while switched on." % _g(req),
             [section("Operating conditions",
                      "With On/Off on, each update requests %s internal charge, %s per simulated second, through the shared draw helper, which takes min(%s × supply factor, pool charge). "
                      "It pumps only when the returned share is above %s and the two circuits together hold more than %s liquid amount. "
                      "Above that share the step is the full step; the request is made even when there is too little liquid to pump." % (_g(req), _g(req * ups), _g(req), _g(cut), _g(req))),
              section("Performance drivers",
                      "Unlike an exchanger it does not stop at equal temperatures: A loses 0.03·qB/(qA+qB) and B gains 0.03·qA/(qA+qB) every update, so B can be driven hotter than A. "
                      "While q stays constant, that is 1.8·qB/(qA+qB) and 1.8·qA/(qA+qB) per simulated second. Remove heat from B with a radiator or exchanger or the transfer stalls as B climbs."),
              section("Capacity per litre",
                      "q is the circuit's stored liquid amount: 0.1 per litre of fresh water, diesel, jet fuel, oil, seawater, slurry or saturated slurry, with no per-liquid factor. Gases add nothing. "
                      "With 1 L in each circuit, qA = qB = 0.1, so each update moves A by -0.015 °C and B by +0.015 °C, -0.9 and +0.9 °C per simulated second, before both drift toward the surroundings by 0.001 of the gap.")],
             [step, floor, f["c_req"], f["c_gate"], f["c_q"], f["c_step"], f["c_ex"], cryo_s, h["q_liquid"], h["filter"]] + N["draw"] + R
             + [T("cryo_cooler"), P("cryo_cooler", "On/Off"), A("cryo_cooler", "water_component_type", "Selects case 0x21 of the fluid update.")],
             [SP_STATIC, TICK])

    # Hydrogen fuel cell.
    o2, h2, water, one = S["cell"]
    cellf = [f[x] for x in ("h_guard", "h_flags", "h_o2", "h_damage", "h_oa", "h_ha", "h_wa", "h_one", "h_add", "h_s")]
    B.family("part-hydrogen-fuel-cell",
             "Each update one fixed reaction turns %s amount of oxygen and %s of hydrogen into %s of water and %s internal charge: at most %s L/s of oxygen and %s L/s of hydrogen into %s L/s of water and %s charge/s." % (
                 fmt(o2), fmt(h2), fmt(water), _g(one), _g(o2 * 600 * ups, 4), _g(h2 * 600 * ups, 4), _g(water * 10 * ups, 4), _g(one * ups)),
             [section("Setup and interactions", "Pair with an electrolyser, which splits fresh water into hydrogen and oxygen using electricity."),
              section("Reaction",
                      "One inlet takes only oxygen and the other only hydrogen into a shared buffer. An undamaged cell then runs at most one reaction per update: it needs at least %s amount of oxygen (%s expanded litres), "
                      "%s of hydrogen (%s L) and %s of free space in its water buffer (%s L). It removes both gases, adds %s amount of fresh water and deposits %s internal charge into the electrical network. "
                      "Water leaves through the outlet port; if it backs up until less than %s is free, reactions stop." % (
                          fmt(o2), _g(o2 * 600, 4), fmt(h2), _g(h2 * 600, 4), fmt(water), _g(water * 10, 4), fmt(water), _g(one), fmt(water))),
              section("Rates",
                      "At %d reactions per simulated second the cell uses %s L/s of oxygen and %s L/s of hydrogen, measured as expanded gas, and makes %s L/s of water and %s charge/s. "
                      "Over 600 reactions, %s simulated seconds, that is %s L and %s L of gas, %s L of water and 600 charge. These are ceilings: thin gas supply or a full water buffer skips reactions." % (
                          ups, _g(o2 * 600 * ups, 4), _g(h2 * 600 * ups, 4), _g(water * 10 * ups, 4), _g(one * ups), _g(600 / ups), _g(o2 * 600 * 600, 4), _g(h2 * 600 * 600, 4), _g(water * 10 * 600, 4))),
              section("Electrical output",
                      "The cell does not check battery demand. It deposits the charge whenever it reacts, and with no electrical network attached the charge is dropped while the gases are still used."),
              section("Space DLC",
                      "The reaction runs only when the Space DLC is owned and enabled in the current session, the same gate the electrolyser and the directional antennas use. Without it the cell makes no water or charge.")],
             cellf + R + [T("hydrogen_fuel_cell"), T("electrolyser"), A("hydrogen_fuel_cell", "water_component_type", "Selects case 34 of the fluid update.")]
             + [new_issues_native(E)[k] for k in ("sp_query", "sp_copy", "sp_server", "sp_setup", "sp_lua")],
             [SP_STATIC, TICK])

    # Laser point sensor.
    den, gate, cone, edge, sx = S["laser"]
    B.family("part-laser-point-sensor",
             "Reports the laser point closest to its view centre inside a %s degree cone, as x and y direction components divided by cos(0.5 rad); the outputs are not angles." % _g(cone),
             [section("Setup and interactions", "Composite number channels 1 and 2 give x and y; on/off channel 1 is set while a point is visible. Match the Wavelength input to the emitting beacon or laser."),
              section("Field of view and outputs",
                      "The sensor accepts a point when the dot product of the unit direction to it with the sensor's forward axis is above %s, which means less than %s degrees from forward: the %s degree field of view the Data Output port states. "
                      "Of the accepted points it reports the one with the largest dot product. Channel 1 is the direction's x component and channel 2 its y component, each divided by %s, the tooltip's cos(0.5). "
                      "Both statements hold: 120 degrees is the cone, and cos(0.5) is only the output scale. A point %d degrees to one side reads %s; at the edge of the cone the output reaches %s, never 1. "
                      "For a point on one axis, the angle from forward is asin(%s × output) (inference from the projection)." % (
                          fmt(gate), _g(cone / 2), _g(cone), fmt(den), 30, _g(sx), _g(edge), fmt(den)))],
             [f["l_gate"], f["l_div"], f["l_store"], f["l_ex"], T("laser_point_sensor"), P("laser_point_sensor", "Data Output"), P("laser_point_sensor", "Wavelength"),
              A("laser_point_sensor", "logic_gate_type", "Value 48.")],
             [SP_PLAIN])

    # Oil Rig Pumpjack B and its parent.
    pj = [f[x] for x in ("p_case", "p_ctor", "p_flag", "p_ports")]
    B.family("part-oil-rig-pumpjack-b",
             "The moving piston of the Oil Rig Pumpjack. It has no ports, and its own update does nothing, so it pumps no oil by itself.",
             [section("Role",
                      "The Oil Rig Pumpjack names this part as its child_name and carries the Fluid Out port. Its tooltip says that lifting this piston with enough force pulls fluid through the pump, and that pumping needs a mechanical force that cycles the piston repeatedly."),
              section("Own update",
                      "Both parts are type 7 multibody components. Definition flag 0x80 makes the multibody update return at once, and this piston has flags 128, so it moves no fluid itself: its own oil output is 0 per update. "
                      "Placed alone it does nothing.")],
             pj + [A("oil_rig_pumpjack_b", "flags", "Value 128 sets bit 0x80."), A("oil_rig_pumpjack_b", "type", "Multibody component."),
                   A("oil_rig_pumpjack", "child_name", "Names the piston."), P("oil_rig_pumpjack", "Fluid Out"), T("oil_rig_pumpjack")],
             [SP_PLAIN])
    fg = fluid_gaps_native(E)
    pump = [fg[k] for k in ("pj_range", "pj_half", "pj_scale", "pj_h", "pj_store", "pj_bias", "pj_dir", "pj_call")]
    well = [fg[k] for k in ("w_room", "w_min", "w_add", "w_debit", "d_rate", "d_min", "d_store")]
    B.family("part-oil-rig-pumpjack",
             "Pumps crude from a finite well buffer out of Fluid Out when a mechanical force cycles its piston, Oil Rig Pumpjack B: the piston sets a chamber of volume 10 × its travel fraction, and a pump_pressure bias of 10000 pushes the excess out.",
             [section("Piston",
                      "The pumpjack names Oil Rig Pumpjack B as its child_name. The piston's own update does nothing (definition flag 0x80), so all pumping runs through this part and its Fluid Out port."),
              section("Pump chamber",
                      "Each update the pumpjack reads the piston's displacement x, its travel range r and the sign s of its mirrored axis, and forms the travel fraction u = clamp((s × x + r ÷ 2) ÷ r, 0, 1). "
                      "It sets the chamber's volume to V = 10 × u, 100 L at full travel. With A the amount already in the chamber, the exchange factor is h = clamp(A − V, 0, 1): fluid leaves only while the chamber holds more than its volume, as when the piston compresses a filled chamber. "
                      "This step changes the chamber's size and adds no crude."),
              section("Outflow",
                      "The pumpjack calls the port solver between Fluid Out and the chamber with bias pump_pressure, 10000, factor h and all species, allowing only flow from the chamber to the port. "
                      "The solver's signed difference is d = P_port − P_chamber − 10000, so the bias pushes crude out against outlet pressure. It is a pressure bias in the transfer, not a rupture pressure or an outlet ceiling. "
                      "The delivered amount still depends on the solver, the pressures on both sides and h."),
              section("Well supply",
                      "A separate branch tops the piston up from the well buffer: q = min(10 × u − A, buffer crude). A positive q moves that crude from the buffer into the piston, so the pumpjack draws a finite supply rather than creating oil. "
                      "The buffer refills from an oil deposit by q = min(free buffer room × 0.05, deposit remaining), and the deposit loses what it gives. "
                      "The deposit used is the non-empty one with the most remaining crude whose region contains the sampling point.")],
             pj + pump + well + [A("oil_rig_pumpjack", "child_name", "Names the piston."), A("oil_rig_pumpjack", "pump_pressure", "Bias the pump branch passes to the port solver: d = P_port − P_chamber − pump_pressure, outflow only."),
                                 A("oil_rig_pumpjack_b", "flags", "Value 128 sets bit 0x80."), P("oil_rig_pumpjack", "Fluid Out"), T("oil_rig_pumpjack")],
             [SP_PLAIN, "The chamber scale and the supply equations are decoded, but delivered volume per stroke or per second depends on piston motion and the connected fluid system. "
              "The piston's motion under a mechanical drive, which deposits a well may draw from, the scheduling of the pump and supply branches and the outflow over a real cycle were not traced, so no amount per stroke or per simulated second is given."])

NU_REPORT = "investigation/nuclear.md"
NU_DATA = "investigation/native/nuclear/nuclear.json"
NU_EXAMPLES = "investigation/native/nuclear/tools/examples.json"
F_NUCLEAR = 0x14041DC40     # nuclear component update, vtable 0x140b74140 slot +0x358, switch on nuclear_component_type
F_NU_POST = 0x14041ED90     # nuclear post-update, slot +0x360: commits the rod's working reaction
F_NU_CTOR = 0x14045FA70     # nuclear component constructor
F_NU_BIND = 0x14041C8E0     # coupling binder: four control_rod couplings into component+0x1f8
F_NU_DAMAGE = 0x14041DC00   # nuclear damage setter, slot +0x20 (leaf)
F_NU_SELECT = 0x140872DE0   # editor property panel that registers the "nuclear type" selector
F_NU_LOADER = 0x140940EA0   # definition reader for nuclear_component_type
F_RAD_SAMPLE = 0x14030F9C0  # radiation sampler: live sources, compartment scalar, contamination index
F_RAD_DEPOSIT = 0x14030F740  # persistent contamination deposit
NU_VTABLE = 0x140B74140
NU_SLOTS = ((NU_VTABLE + 0x358, F_NUCLEAR), (NU_VTABLE + 0x360, F_NU_POST), (NU_VTABLE + 0x20, F_NU_DAMAGE))
NU_CASE = (59, 0x1403C8808)  # logic jump-table entry of the radiation detector
_NU = "nuclear/asm/"
NU_ASM = {
    F_NUCLEAR: (_NU + "update.asm", "0x14041dc40.c"), F_NU_POST: (_NU + "post-update.asm", "0x14041ed90.c"),
    F_NU_CTOR: (_NU + "constructor.asm", "0x14045fa70.c"), F_NU_BIND: (_NU + "coupling-bind.asm", "0x14041c8e0.c"),
    F_NU_DAMAGE: (_NU + "damage-setter.asm", "0x14041dc00.c"), F_NU_SELECT: (_NU + "type-selector.asm", None),
    F_NU_LOADER: (_NU + "type-loader.asm", "0x140940ea0.c"),
    F_RAD_SAMPLE: (_NU + "radiation-sample.asm", "0x14030f9c0.c"), F_RAD_DEPOSIT: (_NU + "contamination-deposit.asm", "0x14030f740.c"),
    F_LOGIC: (_NU + "sensor-case59.asm", None), F_FUEL_INIT: (_NU + "spawn-fuel.asm", "0x1405dafa0.c"),
}
NU_PARTS = ("steam_nuclear_fuel_assembly", "steam_nuclear_fuel_rod", "steam_nuclear_control_rod")
NU_STATIC = ("Static analysis of one build; no game process was run. Reaction, temperature, contamination and detector readings are the game's internal values: "
             "reaction is a rate, not a power in watts, and the detector reading has no stated dose unit.")
NU_POINTER = ("Open questions about coupling tolerances, update order, contamination decay, dose units and the damage event are listed in the "
              "Nuclear fuel assemblies and control rods mechanics article.")


def reactor_steady(n, ci, fuel=1.0, f=0.001):
    """Settled reaction and temperature of equal rods with n fuel neighbours and summed insertion ci, fuel held fixed.

    Inference from the decoded update: returns (g, r, T) with g the per-update growth factor of a disturbance;
    r and T are None when g >= 1 and the reaction climbs to the cap. f is the rod's coolant pull per update
    (0.001 with liquid and total amount 100, full immersion); coolant and surroundings at 20."""
    b, m = 0.1 * fuel, 1 - 0.01 * ci
    g = 0.999 * m * (0.002 * n + 0.997002)
    if g >= 1:
        return g, None, None
    r = b + 0.001998 * m * b * (n - 1) / (1 - g)
    return g, r, 20 + 0.0999 * r / (1 - 0.999 * (1 - f))


def nuclear_native(E):
    """Nuclear fuel assembly, fuel rod and control rod update, radiation sampler and detector, verified once and shared."""
    if hasattr(E, "nuclear"):
        return E.nuclear
    n = E.native
    if not (E.root / NU_REPORT).is_file():
        raise ValueError("Nuclear report missing: " + NU_REPORT)
    for slot, target in NU_SLOTS:
        if struct.unpack("<Q", n.raw(slot, 8))[0] != target:
            raise ValueError("Vtable slot %#x does not point to %#x" % (slot, target))
    if _rtti(n, NU_VTABLE) != "c_scene_vehicle_component_nuclear":
        raise ValueError("RTTI at %#x is not c_scene_vehicle_component_nuclear" % NU_VTABLE)
    if n.base + struct.unpack("<I", n.raw(LOGIC_TABLE + 4 * NU_CASE[0], 4))[0] != NU_CASE[1]:
        raise ValueError("Logic case %d no longer selects %#x" % NU_CASE)
    rep = " Report: %s." % NU_REPORT

    def code(func, address, hexbytes, label, value, detail):
        _wheel_cite(E, func, address, hexbytes, table=NU_ASM)
        return E.code(func, address, hexbytes, label, value, detail + rep)

    def op(func, address, hexbytes, target, label, detail):
        _wheel_cite(E, func, address, hexbytes, table=NU_ASM)
        return E.operand(func, address, hexbytes, target, label, detail + rep)

    near = lambda a, b: math.isclose(a, b, rel_tol=1e-6, abs_tol=1e-12)
    ups = update_rate(E)["ups"]
    data = json.loads((E.root / NU_DATA).read_bytes())
    if (data["build_sha256"] != EXE_SHA256 or data["component_hz"] != ups or data["rtti"] != "c_scene_vehicle_component_nuclear"
            or int(data["vtable"], 16) != NU_VTABLE or int(data["update"], 16) != F_NUCLEAR or int(data["post_update"], 16) != F_NU_POST):
        raise ValueError("Nuclear identity in %s differs from the verified bytes" % NU_DATA)
    for addr, c in data["constants"].items():
        if n.raw(int(addr, 16), 4).hex(" ") != c["bytes"] or ("float32" in c and n.f32(int(addr, 16)) != c["float32"]):
            raise ValueError("Nuclear constant %s in %s differs from the executable" % (addr, NU_DATA))
    defs = {d["definition"].rsplit("/", 1)[1][:-4]: d for d in data["definitions"]}
    vox = {}
    for bid, d in defs.items():
        blk = E.block(bid)
        a = blk["attributes"]
        vox[bid] = E.voxels(bid, "The spawn conversion divides the fuel quantity by this count, so it is the rod's full-fuel quantity." if bid == "steam_nuclear_fuel_rod" else "Listed voxel count.")
        if (blk["name"] != d["name"] or int(a["type"]) != d["type"] or float(a["mass"]) != d["mass"] or float(a["value"]) != d["value"]
                or E.file(DEFS + bid + ".xml")[0] != d["source_sha256"] or vox[bid]["value"] != d["voxel_count"]
                or any(int(a[k]) != d[k] for k in ("nuclear_component_type", "logic_gate_type") if k in d)):
            raise ValueError("%s figures in %s differ from the definition" % (bid, NU_DATA))
    if sorted(defs) != sorted(NU_PARTS + ("radiation_detector",)) or int(E.block("radiation_detector")["attributes"]["logic_gate_type"]) != NU_CASE[0]:
        raise ValueError("Nuclear definitions in %s changed" % NU_DATA)
    labels = {}
    for k, lab in data["nuclear_type_labels"].items():
        addr = int(lab["address"], 16)
        raw = bytes.fromhex(lab["bytes"].replace(" ", ""))
        if n.raw(addr, len(raw)) != raw or n.cstring(addr) != lab["name"] or defs[NU_PARTS[int(k)]]["nuclear_component_type"] != int(k):
            raise ValueError("Nuclear type label %s differs" % k)
        labels[int(k)] = (addr, lab["name"])
    A, R, C = (defs[b] for b in NU_PARTS)
    K = n.f32
    step = K(0x140BAF92C)
    hot = struct.unpack("<I", n.raw(0x14041E159, 4))[0]
    cap = struct.unpack("<I", n.raw(0x14041E135, 4))[0]
    life50 = 1 / (K(0x140BAF854) * ups * K(0x140BB0740))
    pairs = [(C["insertion_change_per_update"], step), (-C["insertion_change_per_update"], K(0x140BB0A08)), (C["input_max"], K(0x140BAFECC)),
             (C["insertion_max"], 1.0), (C["input_min"], 0.0), (C["insertion_min"], 0.0), (C["full_stroke_updates"], round(1 / step)),
             (C["full_stroke_seconds"], round(1 / step) / ups), (A["self_relaxation"], K(0x140BAFEBC)), (A["neighbour_relaxation"], K(0x140BAFEB4)),
             (A["neighbour_reaction_gain"], 1 - A["neighbour_relaxation"]), (A["control_multiplier_per_sum_insertion"], -K(0x140BAFBBC) * K(0x140BAFA24)),
             (A["liquid_exchange_gain"], K(0x140BAF8F8)), (A["rod_exchange_capacity"], K(0x140BB0790)), (A["rod_exchange_cap"], K(0x140BAFCBC)),
             (A["minimum_compartment_total_exclusive"], K(0x140BAFECC)), (A["coolant_radiation_injection"], K(0x140BAF8F8)), (A["neighbour_slots"], 4),
             (R["reaction_min"], 0.0), (R["reaction_max"], K(0x140BB0740)), (R["fuel_baseline_gain"], K(0x140BAFAD0)), (R["reaction_relaxation"], K(0x140BAFEBC)),
             (R["detached_extra_relaxation"], K(0x140BAFEBC)), (R["heat_per_update_per_reaction"], K(0x140BAFAD0)),
             (R["fuel_fraction_per_update_per_reaction"], K(0x140BAF854)), (R["environment_relaxation"], K(0x140BAF8F8)),
             (R["damage_temperature_strictly_above_C"], K(0x140BB0864)), (R["damage_increment_hot_updates"], hot), (R["damage_max"], cap),
             (R["damaged_fuel_loss_max_per_update"], K(0x140BAF898)), (R["nominal_full_fuel_lifetime_at_reaction50_seconds"], life50),
             (R["live_radiation_strength_per_reaction"], K(0x140BAFAD0)), (R["live_radiation_radius_per_strength_m"], K(0x140BB064C)),
             (R["radiation_cross_compartment_radius_penalty_m"], K(0x140BB07D8))]
    if any(not near(x, y) for x, y in pairs) or C["damaged_control"] != "insertion freezes" or (hot, cap) != (300, 50):
        raise ValueError("Nuclear figures in %s differ from the verified bytes" % NU_DATA)
    examples = json.loads((E.root / NU_EXAMPLES).read_bytes())
    worked = []
    for x in examples:
        m = 0.999 * (1 - 0.01 * x["insertion"])
        r = 0.1 * (1 - 0.999002 * m) / (1 - 1.001002 * m)
        g, r2, t2 = reactor_steady(2, x["insertion"])
        if (x["seconds"] != 600 or not near(r, x["frozen_fuel_equilibrium_react"]) or not near(r2, r) or not near(t2, x["frozen_fuel_equilibrium_temp"])
                or not near(20 + 0.0999 * r / 0.001999, t2)):
            raise ValueError("Nuclear worked example differs from the closed form")
        if x["freeze_fuel"]:
            if abs(x["rod"]["temp"] - t2) > 1e-7 or abs(x["rod"]["react"] - r2) > 1e-9 or x["rod"]["fuel"] != 1:
                raise ValueError("Nuclear worked example has not settled")
            worked.append((x["insertion"], r2, t2))
        elif not (0 < 1 - x["rod"]["fuel"] < K(0x140BAF854) * x["seconds"] * ups * r2 and x["rod"]["temp"] < t2):
            raise ValueError("Depleting nuclear example out of range")
    if [w[0] for w in worked] != [0.1, 0.25, 1.0]:
        raise ValueError("Nuclear worked examples changed")
    f = {}

    # Identity and type names.
    f["slot"] = code(F_NU_CTOR, 0x14045FA85, "488d05b4467100488907", "Nuclear component vtable", "%#x" % NU_VTABLE,
                     "The constructor installs this vtable (RTTI c_scene_vehicle_component_nuclear). Its slot +0x358 at %#x holds the update %#x, slot +0x360 the post-update %#x and slot +0x20 the damage setter %#x; the extractor re-reads all three pointers." % (
                         NU_VTABLE + 0x358, F_NUCLEAR, F_NU_POST, F_NU_DAMAGE))
    f["temp0"] = code(F_NU_CTOR, 0x14045FB80, "48c787280400000000a041", "Nuclear starting temperature", "20, reaction 0",
                      "The constructor writes 20 (0x41a00000) to the temperature at +0x428 and 0 to the reaction at +0x42c in one 8-byte store.")
    f["ramp0"] = code(F_NU_CTOR, 0x14045FC0A, "c7878c04000000008041", "Nuclear ambient controller duration", "16 updates",
                      "The constructor gives the surrounding-temperature controller at +0x470 a duration of 16 and starts its target, output and start at 20 (0x14045fc00, 0x14045fc25, 0x14045fc30), as in the heat exchangers.")
    f["loader"] = E.string(F_NU_LOADER, 0x140B5D6B8, "nuclear_component_type", "nuclear_component_type reader",
                           "The definition reader 0x1403168d0 passes definition+0x2cc0 to this routine (0x140318157), which reads the integer attribute nuclear_component_type and stores 0 when it is absent." + rep)
    f["select"] = E.string(F_NU_SELECT, 0x140B42498, "nuclear type", "Nuclear type selector",
                           "The editor property panel registers a selector with this caption whose getter 0x14087fc10 and setter 0x14087fc20 access the edited definition's type field." + rep)
    names = {}
    for k, at, hexbytes in ((0, 0x14087DBB4, "33d2"), (1, 0x14087DBE1, "ba01000000"), (2, 0x14087DC0D, "ba02000000")):
        addr, text = labels[k]
        names[k] = E.string(F_NU_SELECT, addr, text, "Nuclear type %d name" % k,
                            "The selector loads this label just before registering it with value %d (bytes %s at %#x); the game's own name for nuclear_component_type %d, not an inferred enum identifier." % (k, hexbytes, at, k) + rep)
        if n.raw(at, len(hexbytes) // 2).hex() != hexbytes:
            raise ValueError("Selector value at %#x differs" % at)
    f["names"] = names
    f["dispatch"] = code(F_NUCLEAR, 0x14041DCB4, "8b8ac02c000085c90f846f0c000083e9010f84d701000083f9010f8563100000", "Nuclear type dispatch",
                         "0 → 0x14041e931, 1 → 0x14041dea2, 2 → 0x14041dcd4",
                         "The update reads nuclear_component_type at definition+0x2cc0: type 0 (fuel assembly) jumps to the assembly branch, type 1 (fuel rod) to the rod branch and type 2 (control rod) to the control branch; any other value ends the update.")

    # Control rod.
    f["c_damage"] = code(F_NUCLEAR, 0x14041DCD4, "453966080f8559100000", "Control rod damage gate", "damage 0 only",
                         "The control branch runs only while the damage count at component+0x8 is 0; a damaged control rod skips it and keeps its stored insertion.")
    f["c_input"] = code(F_NUCLEAR, 0x14041DCE7, "f3410f10b6f0010000450f57e4f3410f5ff4f3440f1015ca217900f3410f5df2f30f5cf0", "Insertion Target clamp", "clamp(input, 0, 1) − I",
                        "Loads the Insertion Target input (component+0x1f0), clamps it to 0 to 1 (1 from 0x140bafecc) and subtracts the stored insertion I (+0x434).")
    f["c_down"] = op(F_NUCLEAR, 0x14041DD0B, "f30f5f35f52c7900", 0x140BB0A08, "Insertion step limit (−)", "Lower bound of the per-update change.")
    f["c_up"] = op(F_NUCLEAR, 0x14041DD13, "f30f5d35111c7900", 0x140BAF92C, "Insertion step limit (+)", "Upper bound of the per-update change.")
    f["c_store"] = code(F_NUCLEAR, 0x14041DD1B, "f30f58c6f3410f118634040000f3410f118660010000", "Insertion store", "I = I + step; Insertion = I",
                        "Adds the clamped step to I, stores it at +0x434 and writes the same value to the numeric output at +0x160, the Insertion port.")

    # Fuel rod.
    f["r_relax"] = op(F_NUCLEAR, 0x14041DF7D, "f30f101d371f7900", 0x140BAFEBC, "Reaction relaxation",
                      "The rod branch loads this factor for both relaxations below.")
    f["r_loose"] = code(F_NUCLEAR, 0x14041DF8E, "4d39a6a0040000750df3410f11962c040000f30f59d3", "Loose fuel rod branch", "no assembly: R = next; next × 0.999",
                        "Without an associated assembly (+0x4a0 is 0) the rod copies its working reaction (+0x430) into its reaction (+0x42c) and multiplies the working value by 0.999 before the ordinary step, so a loose rod's reaction decays.")
    f["r_base"] = op(F_NUCLEAR, 0x14041DFB0, "f3440f1025171b7900", 0x140BAFAD0, "Fuel baseline gain",
                     "b = this × F, F the fuel fraction at +0x438. The rod then forms r = b + 0.999 × (next − b) (0x14041dfbe-0x14041dfc6). The same register supplies the heating factor.")
    f["r_cap"] = op(F_NUCLEAR, 0x14041DFD3, "f3440f102d64277900", 0x140BB0740, "Reaction cap",
                    "r is clamped to 0 (maxss at 0x14041dfce) and to this (minss at 0x14041dfdc), then stored as the working reaction at +0x430 (0x14041dfe1).")
    f["r_heat"] = code(F_NUCLEAR, 0x14041DFEA, "0f28c2f3410f59c4f3410f588628040000f3410f118628040000", "Heat per reaction", "T = T + 0.1 × r",
                       "Multiplies r by the 0.1 in xmm12 (0x140bafad0) and adds it to the temperature at +0x428 every update. Insertion does not enter directly.")
    f["r_fuel"] = op(F_NUCLEAR, 0x14041E004, "f30f591548187900", 0x140BAF854, "Fuel use per reaction",
                     "F = clamp(F − this × r, 0, 1), stored at +0x438 (0x14041e00c-0x14041e023).")
    f["r_tick"] = code(F_NUCLEAR, 0x14041E041, "f640040f0f858f000000", "Rod surrounding-temperature sample", "every 16 updates",
                       "On updates whose low four bits are 0 the rod calls the surrounding-temperature sample 0x14030fd60 (0x14041e07f) with the assembly's compartment and submits it to its controller at +0x470; every update then advances that controller with 0x1408cde20 (0x14041e0e1).")
    f["r_env"] = op(F_NUCLEAR, 0x14041E0FC, "f3440f101df3177900", 0x140BAF8F8, "Surrounding temperature pull",
                    "T = T + this × (controller output − T), every update after the heating (0x14041e0ef-0x14041e10e).")
    f["r_1500"] = op(F_NUCLEAR, 0x14041E117, "0f2f0d46277900", 0x140BB0864, "Damage temperature",
                     "Compares the temperature after heating and the surrounding pull with this and skips the damage step unless it is strictly above (jbe at 0x14041e11e).")
    f["r_hit"] = code(F_NUCLEAR, 0x14041E120, "418b8e5404000085c97520498b06418b5608ffc2b9320000003bd10f47d1", "Hot damage step", "counter 0 → damage + 1, at most 50",
                      "While hot, when the counter at +0x454 is 0 the rod calls its damage setter (slot +0x20) with min(damage + 1, 50).")
    f["r_300"] = code(F_NUCLEAR, 0x14041E14B, "ffc1b8b5814e1bf7e1c1ea0569c22c0100002bc841898e54040000", "Hot damage counter", "counter = (counter + 1) mod 300",
                      "The counter advances only on hot updates and is not reset when the rod cools, so damage rises on the first hot update and then once per 300 hot updates.")
    f["r_setter"] = code(F_NU_DAMAGE, F_NU_DAMAGE, "83790800750d85d2740dc6815004000001", "Nuclear damage setter", "first damage marks pending processing",
                         "When an undamaged component receives a nonzero damage the setter sets the pending flag at +0x450, which the post-update hands to 0x140325680. It then stores min(value, 50) at +0x8 (0x14041dc20).")
    f["r_event"] = code(F_NUCLEAR, 0x14041E191, "41837e08020f821b030000", "Damage event gate", "damage ≥ 2, once",
                        "The one-time event runs only when the saved byte at +0x451 (serialized as fire) is 0, the engine_overheating (settings+0x35) and vehicle_damage (settings+0x4a) settings are on (0x14041e178, 0x14041e187) and damage is at least 2. It sets +0x451 and calls the event creator 0x140288f70 (0x14041e46c).")
    f["r_record"] = code(F_NUCLEAR, 0x14041E4A9, "c7401800004843c7401c00401c47", "Damage event world record", "200 and 40000",
                         "After the event call the rod writes its position and the binary32 values 200 (0x43480000) and 40000 (0x471c4000) into a new world record.")
    f["r_dloss"] = op(F_NUCLEAR, 0x14041E4D8, "f30f590db8137900", 0x140BAF898, "Damaged fuel loss",
                      "h = this × clamp(0.1 × damage, 0, 1) (0x14041e4b7-0x14041e4d2). Only when F > h (0x14041e4e9) does the rod subtract h from F.")
    f["r_dep"] = op(F_NUCLEAR, 0x14041E505, "f30f590d3f217900", 0x140BB064C, "Damage deposit scale",
                    "The removed h × this is passed to the contamination deposit 0x14030f740 at the rod position (0x14041e515).")
    f["r_src"] = code(F_NUCLEAR, 0x14041E6A1, "450f2f9e300400007233", "Live radiation threshold", "r ≤ 0.001 removes the source",
                      "Compares the 0.001 in xmm11 (0x140baf8f8) with r: at or below it the rod releases its live radiation source (+0x448); above it the rod creates one if needed and adds it to the radiation manager list.")
    f["r_strength"] = code(F_NUCLEAR, 0x14041E86C, "f3410f108e30040000f3410f59cc498b07488b08f30f114918", "Live radiation strength", "s = 0.1 × r",
                           "Each update the source gets the rod position and strength s = r × the 0.1 in xmm12, and the compartment of the associated assembly (0x14041e897).")
    f["spawn"] = code(F_FUEL_INIT, 0x1405DC131, "488b48588b81b80000000f57c0f3480f2ac0f30f5ef0", "Fuel rod spawn fraction", "F = quantity ÷ voxel count",
                      "When a vehicle spawns, the resource initializer divides the rod's fuel quantity by its definition voxel count (definition+0xb8) and stores the result as F (0x1405dc153). A fully supplied rod starts at F = 1.")

    # Fuel assembly.
